-- 028: model-prefixed illustration names for R32 and Mk7 drawings (guides re-pointed; upload the renamed SVGs, delete the old names from the bucket)
update guides set content = $j${"id": "awd-gear-oil", "title": "4Motion gear oil: rear differential & bevel box", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "r32-haldex", "alsoFits": "Mk5 R32; A3/TT 3.2 quattro (same units)", "category": "Drivetrain", "kind": "repair", "variants": {"question": "Which unit?", "hint": "Two gear-oil units besides the Haldex: the rear differential behind the coupling, and the bevel box (transfer case) on the side of the transmission that sends drive to the propshaft. Same oil, same plug sizes.", "options": [{"id": "rear", "label": "Rear differential", "when": "Behind the Haldex coupling, under the rear"}, {"id": "bevel", "label": "Bevel box (transfer case)", "when": "On the passenger side of the DSG, where the propshaft starts"}]}, "glance": {"timeFirst": "30 min each", "timeRepeat": "20 min", "difficulty": 1.5, "cost": "$30–40 per unit", "risk": "Rounded plug hexes · fill plug must open before the drain", "why": "VW calls these fluids lifetime. Owners who've opened them at 100k disagree. Each holds about a litre of gear oil, and the job is two plugs and a pump. Do them with the Haldex and you've done the whole 4Motion system in an afternoon.", "note": "Vortex R32 DIY and the TTRS DIY agree on oil, capacity and torque."}, "heroCap": "Rear differential sits behind the Haldex coupling; the bevel box hangs off the transmission up front. Both: drain plug low, fill plug on the side, fill till it spills.", "lifespan": {"title": "When to expect it", "headline": ["'Lifetime' per VW; owners do it every 40–60k with the Haldex"], "earliest": null, "detail": "No filter, no pump, just gear oil. Whine from the rear on the overrun is a differential bearing complaint, usually after years of dark oil.", "factors": ["Hard use", "Unknown history"], "inspect": ["None; keep the interval"], "confidence": {"level": "community", "n": 3, "note": "Owner practice; factory says lifetime."}}, "should": {"yesIf": ["Doing the Haldex anyway", "Unknown history", "Whine from the rear"], "codes": [], "notes": ["Oil: G 052 145 S2 (75W-90 spec) for both units. About 0.95 L each; a litre bottle per unit.", "Fill plug open first. Every time."], "confidence": {"level": "high", "n": 3, "note": "Consistent across both DIYs and ETKA per the Vortex thread."}}, "parts": [{"tier": "oe", "name": "Gear oil, 1 L per unit", "pn": "G 052 145 S2", "note": "", "price": "$25–35", "links": []}, {"tier": "oe", "name": "Drain and fill plugs", "pn": "N 910 827 01 · N 902 818 02", "note": "Same as the Haldex; replace if rounded", "price": "$6", "links": []}], "aftermarket": [{"name": "Ravenol / Motul 75W-90 meeting the G 052 145 spec", "note": "Fine substitutes; check the spec on the bottle.", "price": "$20–30", "signal": "Meets spec", "links": []}], "tools": [{"name": "8mm and 5mm hex bits, 3/8\" ratchet; fluid pump; pan"}, {"name": "Torque wrench to 30 Nm; level ground"}], "before": ["Car level.", "Clean the plug hexes first.", "Fill plug loosened before the drain comes out."], "steps": [{"n": 1, "title": "Find the plugs", "blocks": [{"t": "text", "b": "Rear differential: behind the Haldex coupling. Fill plug on the side (left), drain on the bottom. Both hex plugs, same sizes as the Haldex.", "only": ["rear"]}, {"t": "text", "b": "Bevel box: on the passenger side of the transmission, where the propshaft leaves. Fill plug on its side, drain on the bottom. Access from below with the belly pan off.", "only": ["bevel"]}, {"t": "ill", "id": "r32-haldex", "cap": "Rear diff behind the coupling; bevel box up front on the transmission."}]}, {"n": 2, "title": "Fill plug, then drain", "blocks": [{"t": "text", "b": "Loosen the fill plug (5mm hex). Drain plug (8mm hex) into a pan; about a litre. Look for metal glitter on the magnet or in the oil."}]}, {"n": 3, "title": "Refill to spill", "blocks": [{"t": "text", "b": "Drain plug in with a new seal."}, {"t": "torque", "label": "Drain plug (8mm hex)", "nm": 30, "c": {"level": "high", "n": 2, "note": "30 Nm (both DIYs)."}}, {"t": "text", "b": "Pump G 052 145 S2 in until it runs back out of the fill hole. No temperature spec on these units. Fill plug in."}, {"t": "torque", "label": "Fill plug (5mm hex)", "nm": 15, "c": {"level": "high", "n": 2, "note": "15 Nm."}}]}, {"n": 4, "title": "The other unit, belly pan on", "blocks": [{"t": "text", "b": "Repeat on the other unit if you're doing both. Belly pan, drive, check for drips."}]}], "alsoReplace": [{"name": "Haldex service", "why": "Same afternoon; see its guide."}, {"name": "Propshaft centre support bearing", "why": "You're looking at the propshaft. A cracked rubber support is a known Mk5 4Motion vibration source."}], "check": {"tab": "Read the oil", "title": "What came out?", "illId": "r32-haldex", "illCap": "Glitter is bad.", "rows": [{"see": "Amber to brown, clean magnet", "means": "Fine.", "do": "Refill."}, {"see": "Black, metallic sheen", "means": "Long overdue; bearings working hard.", "do": "Refill; listen for whine; plan a second change soon."}, {"see": "Chunks", "means": "Something's breaking.", "do": "Specialist."}], "c": {"level": "community", "n": 3, "note": "Owner practice."}}, "aftercare": ["Drip check after a day."], "disagreements": [{"topic": "Lifetime fluid?", "pos": "VW: yes. Owners: no.", "call": "Change it with the Haldex."}], "sources": ["VWVortex 'Mini DIY' (R32 0AV)", "Audizine TTRS drivetrain fluids DIY", "eEuroparts R32 rear differential article"], "embeds": []}$j$::jsonb, updated_at = now() where id = 'awd-gear-oil';
update guides set content = $j${"id": "catback-r32", "title": "Cat-back exhaust (R32)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "r32-exhaust", "alsoFits": "Mk5 R32 only; Mk4 R32 and Golf R systems differ", "category": "Engine", "kind": "upgrade", "variants": {"question": "Which cat-back?", "hint": "All of them use the single 60mm sleeve joint ahead of the cross brace. They differ in volume and in what happens to the stock muffler's vacuum flapper.", "options": [{"id": "resonated", "label": "Resonated (civil)", "when": "Milltek resonated, Borla. Daily-driver volume."}, {"id": "nonres", "label": "Non-resonated (loud)", "when": "Milltek non-res, Magnaflow non-res. You'll be heard."}, {"id": "valved", "label": "Valved (ECS, remote)", "when": "Keeps a muffler valve on a remote; the install PDF this guide follows."}, {"id": "tampa", "label": "Resonator delete ('Tampa mod')", "when": "Cut and weld at a muffler shop. Budget."}]}, "glance": {"timeFirst": "3–4 hr", "timeRepeat": "2 hr", "difficulty": 2, "cost": "$700–1,800 · $100–200 for the Tampa mod", "risk": "Hot parts · a seized sleeve clamp · the propshaft runs right there", "why": "A cat-back swaps the mid-pipe and muffler behind the R32's cats. It's where the VR6 sound lives, it drops weight off the back, and it's a single afternoon with a clamp and some hangers. It doesn't add power on a naturally aspirated six, and it's the classic first R32 mod anyway.", "note": "ECS's Mk5 R32 cat-back PDF is the reference for the stock system; the exhaust megathread covers what owners run and why."}, "heroCap": "Underneath: the stock downpipe with the cats ahead of the cross brace, a single 60mm sleeve joint into the cat-back, mid-pipe running beside the propshaft, centre-exit muffler with the vacuum flapper.", "lifespan": {"title": "When owners do this", "headline": ["Cat-back: the classic first R32 mod. Pipes ahead of the cats rot by 150k on salt-belt cars."], "earliest": null, "detail": "Nothing forces the cat-back; it's sound. High-mileage cars do rust through the downpipe section ahead of the cats, so an exhaust job sometimes starts as a repair.", "factors": ["Want the noise", "Rust belt", "Cams and a tune (headers)"], "inspect": ["Look at the pipes ahead of the cats when the car's up for anything else"], "confidence": {"level": "community", "n": 3, "note": "Owner threads."}}, "should": {"yesIf": ["Want the VR6 to be heard", "Rusted mid-pipe or muffler", "Weight off the back"], "codes": [], "notes": ["The flapper: the stock muffler valve is vacuum-actuated and normally closed, opening with revs for volume. Some cat-backs keep a valve (ECS's is remote-controlled), most delete it. If you keep the factory muffler and want it open all the time, unplugging and capping the vacuum line leaves it closed, not open; owners wire a switch instead.", {"text": "Sleeve clamp joint: the cat-back meets the stock downpipe at a single 60mm sleeve clamp ahead of the cross brace. Every cat-back uses that joint; no cutting."}, {"text": "The Tampa mod is a resonator delete done at a muffler shop: cut the stock resonator out and weld in straight pipe or a larger free-flow resonator. Owners love the sound per dollar; it's loud and a little raspy. Bring the shop the thread so they know what you mean.", "only": ["tampa"]}], "confidence": {"level": "medium", "n": 3, "note": "ECS PDF for the stock system; owner megathread for options and results."}}, "parts": [{"tier": "aftermarket", "name": "Cat-back system", "pn": "see options below", "note": "Mid-pipe, muffler, tips, sleeve clamp; hangers transfer from stock", "price": "$700–1,800", "links": [], "only": ["resonated", "nonres", "valved"]}, {"tier": "aftermarket", "name": "Muffler-shop labour + pipe or resonator", "pn": "—", "note": "", "price": "$100–200", "links": [], "only": ["tampa"]}, {"tier": "oe", "name": "Exhaust hangers (×4), cross-brace nuts", "pn": "—", "note": "Hangers tear; replace", "price": "$40", "links": []}], "aftermarket": [{"name": "Milltek cat-back (resonated / non-resonated)", "note": "The reference R32 system. Resonated is civil; non-res is loud.", "price": "$1,200–1,800", "signal": "Forum favorite", "links": []}, {"name": "Borla cat-back", "note": "Deep and quiet cruising, loud on throttle; owners praise the tone.", "price": "$900–1,200", "signal": "Best daily tone", "links": []}, {"name": "Magnaflow cat-back", "note": "Value; non-resonated attracts attention, per owners.", "price": "$700–900", "signal": "Value", "links": []}, {"name": "ECS valved cat-back", "note": "Keeps a muffler valve with a remote. The PDF this guide follows.", "price": "$1,000–1,300", "signal": "Best documented", "links": [{"store": "ECS install PDF", "url": "https://assets.ecstuning.com/edoc/PDF_14107_VW_MK5_R32_Exhaust_System_Installation_r1.pdf"}]}, {"name": "'Tampa mod' resonator delete", "note": "Budget: cut the resonator, weld in a straight pipe or a bigger resonator. Owners love the sound per dollar.", "price": "$100–200 at a shop", "signal": "Budget", "links": []}], "tools": [{"name": "13mm and 15mm sockets, ratchet, breaker bar; exhaust hanger pliers"}, {"name": "Jack, four stands; penetrating oil; ball-pein hammer for slip joints"}], "before": ["Exhaust cold.", "Soak the sleeve clamp and any flange nuts the night before.", "Lay the new system out and test-fit every slip joint on the floor (ECS: tap them round with a hammer if they don't slide)."], "steps": [{"n": 1, "title": "Raise the car, support the exhaust", "blocks": [{"t": "text", "b": "Four stands. Support the system from below (a jack with a board). Remove the four 13mm nuts holding the chassis cross brace and set the brace aside."}]}, {"n": 2, "title": "Stock cat-back off", "blocks": [{"t": "text", "b": "Loosen the sleeve clamp between the downpipe and the cat-back and slide it forward onto the downpipe. Disconnect the vacuum line from the muffler valve. Pop the two front hangers with the pliers. Unbolt the muffler hangers from the body. Lower the whole system and slide it out."}, {"t": "ill", "id": "r32-exhaust", "cap": "One sleeve joint ahead of the brace, two front hangers, bolted muffler hangers, and the flapper's vacuum line."}]}, {"n": 3, "title": "Tampa mod: to the shop", "only": ["tampa"], "blocks": [{"t": "text", "b": "With the system out (or on the car, if the shop prefers), the resonator section is cut out and straight pipe or a larger resonator is welded in. Ask for the hangers to stay where they were. Skip to the refit."}]}, {"n": 3, "title": "New system in, loose", "only": ["resonated", "nonres", "valved"], "blocks": [{"t": "text", "b": "Transfer the stock hangers to the new mid-pipe and muffler in the same orientation. Extension/mid-pipe into the downpipe with the sleeve clamp, then the muffler, then the tips: all snug, nothing torqued, no impact gun."}, {"t": "text", "b": "Valved: mount the solenoid and control module (ECS used a stud on the driver's strut tower and the underside of the fuse box), tee the short hose into the vacuum line at the check valve ahead of the reservoir under the intake manifold, run the long hose down past the subframe to the muffler, power from an ignition-live fuse with an add-a-circuit.", "only": ["valved"]}]}, {"n": 4, "title": "Clearance, hangers, tips", "caution": true, "blocks": [{"t": "text", "b": "Walk the system: clearance to the propshaft, the subframe and the trunk floor at the mid-pipe; to the heat shields and the cross brace at the front. Hangers level side to side and pitched so the lower hole sits 10–15 mm forward of the upper (they swing back as it heats). Centre the tips in the valance cut-outs and set their depth."}, {"t": "warn", "b": "The propshaft is what a GTI doesn't have. A mid-pipe that kisses it shows up as a vibration at speed and a polished line on the pipe. Check it with the car on the ground too."}]}, {"n": 5, "title": "Tighten front to back", "blocks": [{"t": "text", "b": "Push each joint upward as you tighten its clamp, front to back. Let it settle; re-walk the clearances. Vacuum line to the muffler valve if the new system has one. Cross brace back on (13mm), belly pans."}]}, {"n": 6, "title": "Start, drive, re-check", "blocks": [{"t": "text", "b": "Start it and listen for leaks at the joints. Drive; a new rattle over bumps is a hanger or a heat shield. Re-check every clamp at 500 miles (ECS)."}]}], "alsoReplace": [{"name": "Exhaust hangers", "why": "Rubber, twenty years old, and you have pliers in your hand."}, {"name": "Cross-brace nuts", "why": "Rusty; new ones now."}, {"name": "Look at the pipes ahead of the cats", "why": "High-mileage R32s rot the section before the cats. If yours is thin, the headers guide covers replacing that section."}], "check": {"tab": "How loud?", "title": "How loud do you want it?", "illId": "r32-exhaust", "illCap": "Volume goes up; neighbours' patience goes down.", "rows": [{"see": "Daily driver, want the VR6 note", "means": "Resonated.", "do": "Milltek resonated or Borla."}, {"see": "Weekend car, want to be heard", "means": "Non-resonated.", "do": "Milltek non-res or Magnaflow non-res."}, {"see": "Want it quiet at 7am and loud at 7pm", "means": "Valved.", "do": "ECS valved with the remote."}, {"see": "Budget", "means": "Resonator delete.", "do": "Tampa mod at a muffler shop."}], "c": {"level": "community", "n": 3, "note": "Exhaust megathread."}}, "aftercare": ["Clamps at 500 miles.", "Look at the mid-pipe's propshaft clearance after the first hot drive."], "disagreements": [{"topic": "Power from a cat-back?", "pos": "Vendors imply gains.", "call": "None worth measuring on an NA VR6. It's sound and weight."}, {"topic": "Flapper", "pos": "Delete it, keep it, switch it.", "call": "Most cat-backs delete it. If you keep the stock muffler, wire a switch; capping the vacuum leaves it closed."}], "sources": ["ECS Tuning 'MK5 R32 Valved Exhaust System Installation' PDF (stock system removal, clearances, hangers)", "VWVortex 'Official MkV R32 Exhaust Thread' and 'exhaust system for mk5 r32'", "Milltek, Borla, Magnaflow, USP listings"], "embeds": []}$j$::jsonb, updated_at = now() where id = 'catback-r32';
update guides set content = $j${"id": "coolant-pipe-r32", "title": "Coolant pipe ('crack pipe') & thermostat housing (VR6)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "r32-crackpipe", "alsoFits": "24V VR6: Mk4 R32, 24V GTI/Jetta, A3/TT 3.2 (pipe 022 121 050); 12V VR6 uses a different pipe", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "5–6 hr (with the manifold off)", "timeRepeat": "3 hr", "difficulty": 3, "cost": "$60–200 pipe · $60–150 housing · $30 coolant", "risk": "Coolant everywhere · plastic and aluminium threads · air in the system afterward", "why": "Two plastic parts carry coolant across the top of the VR6: the distribution pipe from the back of the water pump to the thermostat housing, and the housing itself. Both go brittle with heat cycles and both leak, which is why the pipe earned its nickname. You replace them together, with the thermostat and the sensor seals, and billet aluminium versions of the pipe exist so you never do it again.", "note": "R32 owners do this as a preventive job; several did it alongside the SAI delete for room. The access is the intake-manifold-off procedure from the PCV guide."}, "heroCap": "Under the intake manifold: the pipe runs along the head from the water pump at the back to the thermostat housing at the front, with the temperature sensor in the housing. Plastic, plastic, plastic.", "lifespan": {"title": "When to expect it", "headline": ["Commonly weeping by 80,000–120,000 miles or 12–15 years, whichever comes first"], "earliest": "Cracks reported at 60k on hot-climate cars", "detail": "Coolant smell after a drive, a slowly dropping level with no puddle, pink crust on top of the block under the manifold. The thermostat housing's seals and the pipe's o-rings go around the same time the plastic does. Owners who replaced the pipe with aluminium years ago report the plastic housing was the next to go.", "factors": ["Age of the plastic", "Heat cycles", "An SAI system in the way (deleting it frees the area)"], "inspect": ["Coolant level at every fill-up for a month if you smell it", "Flashlight along the top of the block below the manifold: pink crust"], "confidence": {"level": "high", "n": 4, "note": "Vendor listings (ECS, Gruven, iABED) and R32 forums agree on the failure and the fix."}}, "should": {"yesIf": ["Coolant smell or loss with no visible puddle", "Pink crust under the intake manifold", "Thermostat codes or slow warm-up (P0128)", "Doing the PCV / valve cover anyway"], "codes": ["P0128", "P2181"], "notes": ["Pipe: OE 022 121 050 (plastic) or a billet aluminium replacement (GruvenParts, iABED, ECS) with a drain plug. The aluminium pipe is the one to buy; it turns a repeat job into a one-time job.", "Housing: replace the complete thermostat housing with new seals and a new thermostat. Aluminium housings exist too but were out of stock for years; plastic with fresh seals is fine if that's what you can get.", "New o-rings everywhere the pipe seats, and new sensor o-rings. The pipe seats into the housing and the pump with o-rings; owners who reused them leaked again.", "This guide assumes the intake manifold comes off (the PCV guide's access). Some Mk4 owners reach the pipe from below with the manifold on; on the Mk5 the manifold-off route is the one that doesn't cost you a knuckle."], "confidence": {"level": "medium", "n": 4, "note": "Parts and failure pattern well documented; step detail synthesized from 24V listings, the FCP manifold procedure and owner threads. Torques flagged."}}, "parts": [{"tier": "aftermarket", "name": "Billet aluminium coolant pipe (with drain plug)", "pn": "GruvenParts / iABED / ECS 24V", "note": "Replaces 022 121 050", "price": "$150–220", "links": []}, {"tier": "oe", "name": "Coolant pipe, plastic (if you insist)", "pn": "022 121 050", "note": "", "price": "$60–90", "links": []}, {"tier": "oe", "name": "Thermostat housing with seals", "pn": "022 121 111 (confirm by VIN)", "note": "", "price": "$60–150", "links": []}, {"tier": "oe", "name": "Thermostat (87°C) and o-ring", "pn": "—", "note": "Often in the housing kit", "price": "$30", "links": []}, {"tier": "oe", "name": "Coolant temp sensor (G62) and o-rings", "pn": "06A 919 501 A (confirm)", "note": "Cheap, replace", "price": "$20", "links": []}, {"tier": "oe", "name": "Intake manifold gasket, pipe o-rings", "pn": "kit", "note": "", "price": "$30", "links": []}, {"tier": "oe", "name": "G13 coolant concentrate + distilled water", "pn": "G 013 A8J 1G", "note": "About a gallon of concentrate", "price": "$30", "links": []}], "aftermarket": [{"name": "GruvenParts billet crack pipe (24V)", "note": "Lifetime warranty, optional drain valve; they've made these longer than anyone.", "price": "$180–220", "signal": "The original fix", "links": [{"store": "GruvenParts", "url": "https://www.gruvenparts.com/"}]}, {"name": "iABED billet coolant pipe", "note": "Billet with a steel drain plug; 24V VR6 fitment incl. Mk5 R32.", "price": "$150–200", "signal": "Value billet", "links": []}, {"name": "ECS aluminium pipe", "note": "'Engineered to be the last water pipe you'll need to replace.' Same idea.", "price": "$150–200", "signal": "Also fine", "links": []}, {"name": "Eurowise / aluminium thermostat housing", "note": "Metal housing for the other half of the problem, when in stock.", "price": "$150–250", "signal": "If you can get one", "links": []}], "tools": [{"name": "Everything from the PCV guide's manifold procedure (10mm/16mm, 5/6mm hex, 10mm TS, T20–T30)"}, {"name": "Hose-clamp pliers, picks, big drain pans, towels"}, {"name": "Vacuum coolant fill tool (strongly recommended) or a funnel"}], "before": ["Engine cold. Coolant under pressure scalds.", "Drain first, then start on the top of the engine; there's a litre sitting in the pipe.", "Read the PCV guide's access steps; they're reused here word for word."], "steps": [{"n": 1, "title": "Drain the coolant", "blocks": [{"t": "text", "b": "Belly pan off. Lower radiator hose off at the radiator into a pan; reservoir cap off to speed it. Leave the pan; the pipe holds more."}]}, {"n": 2, "title": "Nose to service position", "blocks": [{"t": "text", "b": "Bumper cover off: eight T25s along the bottom edge, three T25s in each wheel well, both lower grilles (T20), unplug the side markers through the grille openings, disconnect the washer-bottle suction hose (have a pan), four T25s under the lower grilles and two T20s in the main grille opening, two T25s at the top corners by the headlights, then the two T25s to the bumper beam. Pull each corner forward and set the cover somewhere safe."}, {"t": "text", "b": "Behind each headlight, remove the two rear-most T30s. Unclip the hood cable behind the driver's headlight. Remove the top four 16mm bumper-beam bolts and loosen the bottom four almost all the way. Pull the top of the radiator support forward: the nose tilts and the engine opens up."}, {"t": "note", "b": "Twenty minutes that turns a knuckle-buster into a job you can see. Every R32 engine-top write-up does it."}]}, {"n": 3, "title": "Intake manifold off", "blocks": [{"t": "text", "b": "Airbox out (clips and tabs; lift). Harness bracket on the driver's side of the head: 10mm nut and stud at the back, T30 at the front; unplug the three throttle-body-side connectors and lay the harness aside. Coil connectors off (lift the tabs with a pick), harness cover off. Walk the main PCV breather hose off the top of the valve cover with a flat screwdriver. Behind the manifold: four vacuum lines by hand and the bracket (10mm triple-square). Throttle body: four 5mm hex. Fuel-line bracket (10mm) on the passenger side. One 10mm triple-square bolt each side of the manifold. Two T30 brackets at the front (dipstick tube, sensors). Vacuum line off the variable-intake solenoid."}, {"t": "text", "b": "Nine manifold bolts, all at the front, long ball-end 6mm hex. Pry the six coils out of the head with a flat screwdriver. Rock the manifold forward to break the gasket's seal and lift it away."}, {"t": "ill", "id": "r32-vr6-top", "cap": "What's under the manifold: valve cover with the oil separator at its front, and the coolant pipe running along the head to the thermostat housing."}, {"t": "warn", "b": "Six open intake ports. Rag them immediately. A dropped bolt into a VR6 port is a head-off job."}]}, {"n": 4, "title": "Sensor, hoses, housing off", "blocks": [{"t": "text", "b": "Unplug the coolant temperature sensor on the thermostat housing and pull its retaining clip. Release the hoses at the housing (clamps). Housing bolts out (10mm; count them), housing off the head with the thermostat. Note the thermostat's orientation."}, {"t": "ill", "id": "r32-crackpipe", "cap": "Pipe from the pump at the back of the head to the housing at the front. Both ends are o-ring joints."}, {"t": "warn", "b": "Aluminium threads under old plastic. Back the bolts out slowly; if one squeaks, stop and oil it. Cross-threading here is a helicoil job with the engine in the car."}]}, {"n": 5, "title": "Pipe out", "caution": true, "blocks": [{"t": "text", "b": "Release any bracket bolt on the pipe. Pull the pipe forward out of the water pump's port (o-ring joint at the back); it comes out toward the front now that the housing is off. Expect the last of the coolant. Look at the old pipe: a hairline at a hose spigot or the pump end is the usual crack."}, {"t": "warn", "b": "If the pipe won't move, it's the o-ring, not a bolt you missed. Twist and pull; don't pry against the head."}]}, {"n": 6, "title": "New pipe and housing", "blocks": [{"t": "text", "b": "Clean both o-ring bores (pump port and housing seat) and the housing face on the head. New o-rings on the pipe, wetted with coolant; pipe into the pump port first, fully seated. New thermostat in the new housing in the orientation you noted, new seal, housing onto the head and onto the pipe's front end together; bolts snug in a criss-cross. New sensor with its o-ring and clip. Hoses and clamps."}, {"t": "torque", "label": "Thermostat housing bolts (M6)", "nm": 10, "c": {"level": "single", "n": 1, "note": "No factory figure confirmed this pass; M6 into aluminium, 10 Nm is the usual VW value and owners say 'snug'. Flagged."}}]}, {"n": 7, "title": "Manifold on, engine dressed, nose back", "blocks": [{"t": "text", "b": "New manifold gasket pressed into the manifold (pick the old one out; wipe the head face). Manifold on with nothing trapped; all nine bolts started by hand, then tightened middle-out."}, {"t": "torque", "label": "Intake manifold bolts (6mm hex ×9)", "nm": 13, "c": {"level": "high", "n": 1, "note": "13 Nm (FCP Euro procedure on a Mk5 R32)."}}, {"t": "text", "b": "Brackets (T30), variable-intake vacuum line, coils in (tab side per the connectors), harness and cover, manifold side bolts (10mm TS), driver's-side harness bracket (ground stud at the rear hole), PCV breather hose onto the cover, fuel-line bracket, four vacuum lines and their bracket, throttle body (5mm hex, hand-start), airbox and MAF."}, {"t": "text", "b": "Nose: lift it back, four T30s behind the headlights, top beam bolts by hand then all eight to torque (16mm), then the cover in reverse: two beam T25s, side markers, washer hose, grilles, corner screws, bottom edge, wheel wells."}]}, {"n": 8, "title": "Fill and bleed", "caution": true, "blocks": [{"t": "text", "b": "Lower hose on. Fill with 50/50 G13, ideally with a vacuum fill tool, which pulls the air out of the pipe and the heater core in one go. Without one: fill slowly, cap off, heater on hot, idle until the thermostat opens and the level drops, top up, repeat, cap on."}, {"t": "warn", "b": "Air pocket at the thermostat means the gauge reads cold and then spikes. Watch it the whole first warm-up."}]}, {"n": 9, "title": "Heat-cycle and re-check", "blocks": [{"t": "text", "b": "Drive, cool fully, top up. Flashlight along the head under the manifold after three heat cycles. Belly pan on when it's dry."}]}], "alsoReplace": [{"name": "Oil separator (PCV) and valve cover gasket", "why": "Same access. Do them now (its guide)."}, {"name": "Coolant hoses at the housing", "why": "Hardened at both ends; cheap now, a leak later."}, {"name": "Water pump", "why": "The pipe seats into it; if the pump is original at 100k, forums say do it."}, {"name": "SAI delete", "why": "Owners who removed the secondary air pump and hoses got the room back permanently. Emissions-legal status varies; decide for yourself."}], "check": {"tab": "Where's the leak?", "title": "Where is the coolant going?", "illId": "r32-crackpipe", "illCap": "Crust tells you which end.", "rows": [{"see": "Crust at the front, by the housing", "means": "Housing seals or the pipe's front o-ring.", "do": "Both parts anyway."}, {"see": "Crust toward the back of the head", "means": "Pipe at the pump end.", "do": "Pipe + o-rings; housing while you're there."}, {"see": "No trace, level dropping", "means": "Heater core or internal.", "do": "Pressure test before opening the top of the engine."}], "c": {"level": "community", "n": 3, "note": "Owner threads."}}, "aftercare": ["Level check after each of the first three drives.", "Aluminium pipe with a drain plug: future flushes are five minutes."], "disagreements": [{"topic": "Manifold off?", "pos": "Mk4 owners sometimes reach under.", "call": "Off. It's the FCP procedure and you'll want the room."}, {"topic": "Plastic or billet pipe?", "pos": "Plastic is cheaper.", "call": "Billet. This is the job you don't want to do twice."}], "sources": ["GruvenParts, iABED and ECS 24V crack pipe listings (part supersession, drain plug)", "R32OC 'MK5 R32 crack pipe and thermostat housing' thread", "VWVortex 'Common MKV R32 Issues Report'", "Humble Mechanic R32 thermostat/crack pipe video (24V, Mk4)", "FCP Euro Mk5 R32 valve cover procedure (manifold access, torques)", "VWVortex 12V crack pipe DIY (technique)"], "embeds": []}$j$::jsonb, updated_at = now() where id = 'coolant-pipe-r32';
update guides set content = $j${"id": "haldex-service", "title": "Haldex (4Motion) fluid & filter service", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "r32-haldex", "alsoFits": "Gen 2 Haldex cars: Mk5 R32, Audi A3 8P quattro 3.2, TT 8J quattro (rear diff prefix 0AV)", "category": "Drivetrain", "kind": "repair", "glance": {"timeFirst": "1 hr", "timeRepeat": "30 min", "difficulty": 2, "cost": "$60–90 (oil + filter)", "risk": "Small plugs in soft aluminium · easy to round the hex", "why": "The Haldex coupling is the clutch pack that sends torque to the rear axle when the fronts slip. It runs in its own oil with a pump and a filter, and neglected oil is what kills the pump and glazes the clutches. Every R32 guide says the same thing: do it every 40k, and do it on purchase if there are no records.", "note": "Two forum DIYs and two vendor articles agree on the procedure; they differ on interval, recorded below."}, "heroCap": "Under the rear of the car: propshaft → Haldex coupling (its own oil, pump and filter) → rear differential (gear oil). Two units, two oils, plugs on each.", "lifespan": {"title": "When to expect it", "headline": ["Every 40,000 miles for oil and filter, or every 20,000 for oil if you drive it hard"], "earliest": "Immediately on a used car without records", "detail": "The system engages only when it needs to, so a tired Haldex gives no warning until the pump fails or the AWD light comes on. Dark, burnt-smelling oil is the sign you were late. The filter starves the pump when it clogs.", "factors": ["Track or launch use", "Towing (rare on an R32)", "Unknown history"], "inspect": ["Nothing to inspect from outside; keep the interval"], "confidence": {"level": "high", "n": 4, "note": "Interval and consequences agree across ECS, eEuroparts and owner DIYs."}}, "should": {"yesIf": ["40k since the last service, or unknown", "AWD fault light, or the rear never seems to engage", "You just bought the car"], "codes": [], "notes": ["Oil: G 055 175 A2 for the Mk5 R32's Gen 2 unit (rear diff prefix 0AV). Gen 4 cars (0BR) take G 060 175 A2. Haldex oil is specific; nothing else goes in.", "Filter: 02D 598 574 (kit with o-ring). Some kits list the old 02D 525 558 A; buy the kit for your generation.", "New fill is 0.85 L; a drain-and-fill takes about 0.65 L. One litre bottle covers it.", "The pump has a strainer screen you can pull and clean while the oil is out; owners who've had pump failures wish they had."], "confidence": {"level": "high", "n": 4, "note": "Part numbers, capacities and torques consistent across the Vortex R32 DIY, the TTRS DIY and vendor kits."}}, "parts": [{"tier": "oe", "name": "Haldex oil, 1 L", "pn": "G 055 175 A2", "note": "Gen 2 (0AV) units", "price": "$30–40", "links": []}, {"tier": "oe", "name": "Haldex filter kit", "pn": "02D 598 574", "note": "Filter + o-ring", "price": "$25–40", "links": []}, {"tier": "oe", "name": "Drain plug (8mm hex) and fill plug (5mm hex)", "pn": "N 910 827 01 · N 902 818 02", "note": "Replace if the hex is rounded", "price": "$6", "links": []}], "aftermarket": [{"name": "ECS / UroTuning Haldex service kits", "note": "Oil, filter and o-ring in one box; some add a magnetic drain plug.", "price": "$60–90", "signal": "One-box pick", "links": [{"store": "ECS R32 maintenance article", "url": "https://blog.ecstuning.com/top-mods-and-maintenance-for-your-vw-mk5-r32/"}]}], "tools": [{"name": "8mm and 5mm hex bits on a 3/8\" ratchet (clean the sockets out first)"}, {"name": "Fluid pump or a syringe with a hose; drain pan; T30 for the filter cover if fitted"}, {"name": "Torque wrench to 30 Nm; ramps or four stands so the car is level"}], "before": ["Car level. There's no dipstick; the level is the fill plug.", "Clean the plug hexes with a pick before you put a bit in them; a rounded hex here is a bad day.", "Warm oil drains better: a short drive first."], "steps": [{"n": 1, "title": "Find the unit", "blocks": [{"t": "text", "b": "Under the rear, the Haldex coupling is the cylindrical unit on the front of the rear differential where the propshaft arrives. Fill plug on the left side near the control module; drain plug on the bottom centre; filter on the right side behind a heat shield."}, {"t": "ill", "id": "r32-haldex", "cap": "Coupling in front, differential behind. Don't mix the oils."}]}, {"n": 2, "title": "Fill plug first, then drain", "blocks": [{"t": "text", "b": "Loosen the fill plug (5mm hex) first, so you know you can refill before you empty it. Then the drain plug (8mm hex) into a pan. Expect about 0.65 L. Look at it: dark and burnt means you were late."}]}, {"n": 3, "title": "Filter", "blocks": [{"t": "text", "b": "Right side of the unit: remove the filter cover, pull the old filter, new o-ring and filter, cover back. If the heat shield fights you, a stubby ratchet helps. While the oil is out, the pump's strainer screen can be pulled and cleaned; follow the kit or a video for its location on your unit."}]}, {"n": 4, "title": "Plug and fill", "blocks": [{"t": "text", "b": "Drain plug in with a new seal ring."}, {"t": "torque", "label": "Haldex drain plug (8mm hex)", "nm": 30, "c": {"level": "high", "n": 2, "note": "30 Nm (Vortex R32 DIY, TTRS DIY)."}}, {"t": "text", "b": "Pump oil in through the fill hole until it runs back out (about 0.65 L on a drain-and-fill). Fill plug in."}, {"t": "torque", "label": "Haldex fill plug (5mm hex)", "nm": 15, "c": {"level": "high", "n": 2, "note": "15 Nm (Vortex R32 DIY)."}}]}, {"n": 5, "title": "Drive, re-check", "blocks": [{"t": "text", "b": "Short drive, back on level ground, fill plug out: top up until it just spills, plug in. Some owners check with the oil at 20–40°C via VCDS; on the R32 the manual gives no temperature, so cold fill-to-spill plus a warm top-up is the practice."}]}], "alsoReplace": [{"name": "Rear differential and bevel box oil", "why": "Same afternoon, same plug sizes, and nobody else will remind you. See the 4Motion gear oil guide."}, {"name": "Haldex pump strainer", "why": "Oil is out; pull and clean it."}, {"name": "DSG service", "why": "Same 40k interval; do them together."}], "check": {"tab": "Read the oil", "title": "What came out?", "illId": "r32-haldex", "illCap": "Colour and smell.", "rows": [{"see": "Amber, thin, faint smell", "means": "On schedule.", "do": "Standard service."}, {"see": "Dark, burnt smell, flakes", "means": "Overdue; clutches have been hot.", "do": "Service, clean the strainer, service again at 10k."}, {"see": "AWD light after service", "means": "Air in the pump or a failing pump.", "do": "Drive a few cycles; if it persists, pump."}], "c": {"level": "community", "n": 3, "note": "Owner DIYs and vendor articles."}}, "aftercare": ["Level re-check after the first drive.", "Note the mileage; 40k or sooner."], "disagreements": [{"topic": "Interval", "pos": "40k oil and filter (ECS, factory) vs 20k oil / 40k filter (eEuroparts).", "call": "40k is the factory line; a 20k oil change is cheap on a car that gets driven hard."}, {"topic": "Level at temperature?", "pos": "The TTRS DIY checks at 20–40°C via VCDS; the R32 DIY says no temperature spec.", "call": "Cold fill-to-spill, warm top-up."}, {"topic": "Which oil", "pos": "G 055 vs G 060 in Audi capacity charts.", "call": "By rear-diff prefix: 0AV = G 055 175 A2."}], "sources": ["VWVortex 'Mini DIY: drain/fill bevel box, Haldex and rear differential' (R32)", "Audizine TTRS drivetrain fluids DIY (same Gen 2 hardware)", "eEuroparts R32 rear differential & Haldex DIY", "ECS 'Top Mods and Maintenance for your VW MK5 R32'", "UroTuning / VAG Garage kit listings (part numbers)"], "embeds": []}$j$::jsonb, updated_at = now() where id = 'haldex-service';
update guides set content = $j${"id": "headers-r32", "title": "Headers & high-flow cat pipes (R32)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "r32-exhaust", "alsoFits": "Mk5 R32 only; Mk4 R32 and Golf R systems differ", "category": "Engine", "kind": "upgrade", "variants": {"question": "How far?", "hint": "Headers replace the two cast manifolds; the pipes that connect them to the cat-back can keep high-flow cats or run catless.", "options": [{"id": "catted", "label": "Headers + high-flow catted pipes", "when": "The street version. Codes are manageable with a tune."}, {"id": "catless", "label": "Headers + test pipes", "when": "Off-road only. Loud, and the ECU will complain without a tune."}]}, "glance": {"timeFirst": "a full day, often two", "timeRepeat": "6 hr", "difficulty": 4, "cost": "$1,500–2,500 headers · $500–1,200 pipes", "risk": "Rear manifold against the firewall · snapped studs · emissions", "why": "Headers are the one exhaust part that makes real power on a naturally aspirated VR6, and only when paired with cams and a tune. The rear manifold sits against the firewall and comes out blind, which is why owners call this a day by itself. If you're going forced induction instead, stop: the turbo kit brings its own manifold and this guide doesn't apply.", "note": "Owner reports from the R32 exhaust megathread; there is no complete public install sheet for R32 headers, so the steps are at the level owners describe."}, "heroCap": "Twin cast manifolds at the front and back of the VR6 into the downpipe with its cats. Headers replace the manifolds; the connecting pipes decide whether the cats stay.", "lifespan": {"title": "When owners do this", "headline": ["With cams and a tune, or when the pipes ahead of the cats have rotted through"], "earliest": null, "detail": "On a stock engine the gain from headers is small and expensive. With Schrick 268/264 cams and a tune it's the combination owners on the megathread run. High-mileage salt-belt cars sometimes get here by necessity: the section ahead of the cats rusts.", "factors": ["Cams and a tune", "Rusted downpipe section", "Track use"], "inspect": ["Pipes ahead of the cats whenever the car's up"], "confidence": {"level": "community", "n": 3, "note": "Exhaust megathread."}}, "should": {"yesIf": ["Cams and a tune on the way or done", "Rotted pipes ahead of the cats", "You're staying naturally aspirated and want the last few horsepower"], "codes": [], "notes": [{"text": "High-flow cats keep the car closer to legal and keep the smell down. Expect P0420/P0430 to need a tune's attention anyway.", "only": ["catted"]}, {"text": "Test pipes remove the emissions equipment: not street-legal in most of the US, and the ECU throws P0420/P0430 without a tune or spacers. Know what you're buying.", "only": ["catless"]}, "Turbo owners: skip this. Every complete turbo kit for the R32 brings its own manifold and downpipe (see the turbo kit guide)."], "confidence": {"level": "medium", "n": 3, "note": "Owner reports; no manufacturer procedure available for R32 headers."}}, "parts": [{"tier": "aftermarket", "name": "Headers (pair)", "pn": "Milltek manifolds; others by quote", "note": "", "price": "$1,500–2,500", "links": []}, {"tier": "aftermarket", "name": "Connecting pipes with high-flow cats", "pn": "USP catted, Scorpion, Milltek", "note": "", "price": "$800–1,200", "links": [], "only": ["catted"]}, {"tier": "aftermarket", "name": "Test pipes", "pn": "USP race pipe", "note": "Off-road", "price": "$500–800", "links": [], "only": ["catless"]}, {"tier": "oe", "name": "Manifold gaskets, new manifold nuts/studs, flange gaskets, O2 sensor anti-seize", "pn": "—", "note": "Buy a stud kit before you start", "price": "$80", "links": []}], "aftermarket": [{"name": "Milltek manifolds + downpipes", "note": "The megathread's reference header set; sold with matching downpipes.", "price": "$2,000–3,000", "signal": "Reference set", "links": []}, {"name": "USP downpipes / race pipe", "note": "The pipes-only upgrade of choice: catted and catless versions for the stock manifolds or headers.", "price": "$600–1,000", "signal": "Pipes pick", "links": []}, {"name": "Scorpion downpipes with high-flow cats", "note": "Owner-reported alternative on the megathread.", "price": "$700–1,000", "signal": "Alternative", "links": []}], "tools": [{"name": "13, 15, 16mm sockets and wrenches; triple-square bits for flange hardware; long extensions and a wobble; O2 sensor socket"}, {"name": "Torch or induction heater, penetrating oil, stud extractor and thread chaser; new studs on hand"}, {"name": "Jack, four stands; a mirror and a light for the rear bank"}], "before": ["Exhaust cold. Soak every manifold nut and flange nut the night before.", "Order a stud kit and gaskets before you start; a snapped stud with no spare ends the day.", "Read the cat-back guide first: the whole system behind the cats comes out for this."], "steps": [{"n": 1, "title": "Cat-back out", "blocks": [{"t": "text", "b": "Cross brace (4× 13mm), sleeve clamp, flapper vacuum line, hangers, muffler hangers, and the cat-back is out (cat-back guide, steps 1–2)."}, {"t": "ill", "id": "r32-exhaust", "cap": "Everything behind the cats comes out first."}]}, {"n": 2, "title": "Downpipe section off", "caution": true, "blocks": [{"t": "text", "b": "Unplug the O2 sensors (label which is which). Flange nuts at both manifolds (soak, heat if needed), any bracket to the transmission, and work the downpipe assembly out past the subframe. Transfer the O2 sensors to the new pipes with anti-seize on the threads."}, {"t": "warn", "b": "Manifold studs snap. Heat, oil, patience, and a stud kit on the shelf before you start."}]}, {"n": 3, "title": "Front manifold off", "blocks": [{"t": "text", "b": "Heat shield off. Manifold nuts from the front; the front bank is the easy one. Manifold off, gasket face cleaned."}]}, {"n": 4, "title": "Rear manifold off", "caution": true, "blocks": [{"t": "text", "b": "The rear manifold sits against the firewall. Heat shield out from below. Nuts come off from below and behind with extensions, a wobble and a mirror; some owners drop the rear of the engine slightly on the mounts for room. Manifold out downward."}, {"t": "warn", "b": "Reached blind. Label the sockets that fit before you're under there, and don't round a nut you can't see."}]}, {"n": 5, "title": "Headers in", "blocks": [{"t": "text", "b": "New gaskets, headers on with new nuts in a criss-cross, rear first while you still have room. Heat shields per the header maker (often modified or deleted)."}, {"t": "torque", "label": "Manifold nuts (M8)", "nm": 25, "c": {"level": "single", "n": 1, "note": "25 Nm is the usual VW M8 exhaust-manifold value; no header-maker figure confirmed. Flagged."}}]}, {"n": 6, "title": "Pipes to the headers", "blocks": [{"t": "text", "b": "Connecting pipes to the header flanges with new gaskets, O2 sensors in, pipes routed clear of the subframe and the propshaft.", "only": ["catted", "catless"]}]}, {"n": 7, "title": "Cat-back back on, tighten, drive", "blocks": [{"t": "text", "b": "Cat-back in per its guide (loose, clearances, hangers, tighten front to back). Start it and check every flange for leaks (a ticking exhaust leak at the manifold is a gasket). Tune before you drive it hard; re-torque the manifold nuts after the first heat cycle."}]}], "alsoReplace": [{"name": "O2 sensors", "why": "If original, new ones now save a second flange fight."}, {"name": "Cams and a tune", "why": "Headers without them is expense without result."}, {"name": "Motor mounts", "why": "If you dropped the engine for the rear manifold, look at them."}], "check": {"tab": "Worth it?", "title": "Are headers worth it on your car?", "illId": "r32-exhaust", "illCap": "Depends entirely on what else is done.", "rows": [{"see": "Stock engine, want sound", "means": "Wrong part.", "do": "Cat-back."}, {"see": "Cams + tune, staying NA", "means": "This is the combination.", "do": "Headers + catted pipes."}, {"see": "Thinking about a turbo", "means": "Kit brings its own manifold.", "do": "Turbo kit guide; skip this."}], "c": {"level": "community", "n": 3, "note": "Megathread."}}, "aftercare": ["Re-torque manifold nuts after the first heat cycle.", "Watch for exhaust smell in the cabin: a rear-manifold leak sits right under the cowl."], "disagreements": [{"topic": "Gain on a stock engine?", "pos": "Vendors: 15–20 hp. Owners: hard to feel.", "call": "Do it with cams or not at all."}, {"topic": "Drop the engine for the rear bank?", "pos": "Some do, some don't.", "call": "If your hands don't fit, drop it an inch on the mounts rather than round a nut."}], "sources": ["VWVortex 'Official MkV R32 Exhaust Thread' (owner setups: Milltek manifolds, Scorpion/USP pipes, Schrick cams)", "ECS Mk5 R32 exhaust PDF (cat-back removal)", "Milltek, USP, Scorpion listings"], "embeds": []}$j$::jsonb, updated_at = now() where id = 'headers-r32';
update guides set content = $j${"id": "intake-mk7", "title": "Aftermarket intake install", "fits": "2015–2021 VW GTI (Mk7 / Mk7.5) · 2.0T TSI Gen 3", "heroId": "mk7-intake", "alsoFits": "MQB Gen 3 1.8T/2.0T: Golf, Golf R, A3/S3 8V (kits list them together; Golf R and S3 get an SAI block-off instead of the adapter)", "category": "Engine", "kind": "upgrade", "variants": {"question": "Which intake are you installing?", "hint": "Two architectures. Full kits replace the airbox with a heat shield, cone filter and pipe; 034's X34/P34 keeps the factory lower box and replaces the lid and inlet.", "brandSpecific": true, "options": [{"id": "ie", "label": "Integrated Engineering V2 (full kit)", "when": "Heat shield, 5\" cone, inlet pipe; reroutes a coolant line. Full PDF.", "brand": true}, {"id": "o34", "label": "034Motorsport X34 / P34 (factory lower box)", "when": "Carbon or plastic upper on the stock lower box; baffle removed. Full PDF.", "brand": true}, {"id": "cts", "label": "CTS Turbo IT-270 (full kit)", "when": "Heat shield and pipe; brief sheet.", "brand": true}, {"id": "other", "label": "Other full kit (Racingline R600, APR, Unitronic, Eventuri)", "when": "Same shape as the IE path; follow the kit sheet.", "brand": false}]}, "glance": {"timeFirst": "1–1.5 hr", "timeRepeat": "45 min", "difficulty": 2, "cost": "$350–800 · carbon lids and R600-class kits more", "risk": "Some kits open the cooling system · plastic grommet brackets snap · SAI fitting must be kept", "why": "On a stock IS20 turbo an intake is worth a handful of wheel horsepower, sound and throttle feel; with a tune or an IS38 the factory box and the turbo inlet pipe become real restrictions and the intake is where the aftermarket starts. Three kits have complete public install guides, which is why this guide can be specific, and independent dyno tests exist, which is why it can be honest about the gains.", "note": "IE's and 034's PDFs are the references; CTS has a sheet. Owners report about an hour."}, "heroCap": "Schematic of a full-replacement kit: heat-shielded cone filter where the airbox was, pipe and silicone coupler to the turbo inlet, SAI fitting and vacuum line kept, and (IE) the factory coolant line that ran through the airbox area rerouted in silicone.", "lifespan": {"title": "When owners do this", "headline": ["First or second mod; before or with a Stage 1 tune"], "earliest": null, "detail": "Nothing wears out. Tuned and IS38 cars benefit most, and IS38 owners pair the intake with a larger turbo inlet pipe because the factory inlet is the next restriction.", "factors": ["Tune", "IS38 swap planned", "Want the turbo noise"], "inspect": ["Cone filter every oil change; clean per the maker"], "confidence": {"level": "community", "n": 3, "note": "Forum consensus; FCP Gen 3 guide."}}, "should": {"yesIf": ["Tuned, or planning to be", "IS38 swap planned (do the inlet pipe too)", "Want induction and turbo noise"], "codes": [], "notes": ["Secondary air injection: US GTIs have an SAI line into the airbox. Every real kit provides an adapter (GTI, Golf, A3) or a block-off (Golf R, S3). Leave it open and you'll have a code and an unmetered leak.", {"text": "IE V2 removes a factory coolant line that runs across the airbox area and replaces it with a silicone hose. That means coolant loss, a cold engine, and the two included silicone caps used quickly. It's a two-minute step with a mess if you rush it.", "only": ["ie"]}, {"text": "034 keeps the factory lower airbox and its two rubber grommet posts; you remove the internal baffle (tight; wiggle it) and fit their upper. Least invasive of the full-featured kits.", "only": ["o34"]}, {"text": "CTS IT-270 is a full-replacement kit like IE's; follow the sheet's clamp order and check whether your revision touches the coolant line.", "only": ["cts"]}, {"text": "Racingline R600 and APR use a larger MAF housing and expect their own tune calibration; check with your tuner before buying. Eventuri is the premium carbon option.", "only": ["other"]}, "Turbo inlet pipe: not required, but the natural companion. IE's and 034's TIPs bolt to the turbo with one M8 (9 Nm per 034) and need coil 1 out for room (IE). Both intake kits ship the coupler for it."], "confidence": {"level": "high", "n": 3, "note": "Two complete manufacturer PDFs plus a sheet; SAI and coolant details straight from them."}}, "parts": [{"tier": "aftermarket", "name": "Intake kit", "pn": "the kit you chose above", "note": "Shield/upper, filter, pipe, couplers, clamps, SAI adapter, vacuum fitting", "price": "$350–800", "links": []}, {"tier": "oe", "name": "Coolant, G13, for the top-up", "pn": "—", "note": "IE path", "price": "$15", "links": [], "only": ["ie"]}, {"tier": "aftermarket", "name": "Turbo inlet pipe (optional companion)", "pn": "IE IEINCI10 · 034-108-5011", "note": "Same afternoon", "price": "$150–250", "links": []}], "aftermarket": [{"name": "Integrated Engineering V2 cold air intake", "note": "Heat shield in two pieces, 5\" cone, cast inlet pipe, couplers for stock or IE inlet, coolant reroute, SAI adapter. Optional carbon lid. The most complete PDF.", "price": "$400–500 (+$200 CF lid)", "signal": "Best documented", "links": [{"store": "IE install guide (PDF)", "url": "https://pbie.s3.amazonaws.com/guides/IE%20MQB%20CAI%20Install%20Guide%20IEINCI11_IEINCI12.pdf"}]}, {"name": "034Motorsport X34 (carbon) / P34 (plastic)", "note": "Replaces the upper box and inlet on the factory lower box; baffle removed; SAI provision; 2.75\" coupler. Torques in the PDF.", "price": "$300 (P34) – $700 (X34)", "signal": "Least invasive", "links": [{"store": "034 X34 install guide (PDF)", "url": "https://www.034motorsport.com/docs/034-108-1005-034motorsport-mqb-audi-volkswagen-gen3-18t-20t-a3-s3-tt-gti-golf-r-carbon-fiber-air-intake-install-instructions-diy-guide.pdf"}]}, {"name": "CTS Turbo IT-270", "note": "Full-replacement kit with heat shield; sheet hosted by ECS.", "price": "$350–450", "signal": "Tuner pick", "links": [{"store": "CTS install guide (PDF)", "url": "https://assets.ecstuning.com/edoc/CTS-IT-270R-V2.3.pdf"}]}, {"name": "Racingline R600 / APR / Unitronic / Eventuri", "note": "Full kits; R600 and APR built around larger MAF housings and their tunes; Eventuri is carbon and priced like it.", "price": "$500–1,200", "signal": "Tune-matched / premium", "links": []}], "tools": [{"name": "T25 Torx, 7mm socket, flat and Phillips screwdrivers, hose-clamp pliers"}, {"name": "4mm allen (shield bolts, SAI fitting); 2.5mm for IE's carbon lid", "only": ["ie", "o34", "cts", "other"]}, {"name": "Rags and a small pan; the kit's two silicone caps at hand", "only": ["ie"]}], "before": ["Engine completely cold (the IE path opens the cooling system).", "Lay the kit out against its list; identify which coupler is for a stock inlet vs an aftermarket inlet pipe.", "Don't force the airbox's plastic grommet brackets; they break."], "steps": [{"n": 1, "title": "What you get", "blocks": [{"t": "text", "b": "Honest numbers first. On a stock IS20 turbo an intake is worth single-digit wheel horsepower; with a tune it's mid-teens; the eye-catching '30 whp' figure in 034's test is the gain right before redline, not the peak. Racingline says it plainly about their own R600: the factory box is adequate until about 300 bhp. Buy an intake for sound, response and headroom, and expect the dyno to agree with the chart, not the ad."}, {"t": "chart", "title": "Measured gain over the stock airbox (peak, wheel figures where given)", "unit": "whp", "baseline": "Stock airbox", "bars": [{"label": "Stock airbox", "v": 0}, {"label": "Independent multi-kit test, stock turbo", "v": 6.5, "note": "median of several kits vs stock (MyGolfMk7); mean 7.8"}, {"label": "Eventuri, IS38 car (~360 whp)", "v": 7, "note": "independent test, aftermarket inlet on both"}, {"label": "034 X34, Stage 1 tune", "v": 10, "note": "vendor dyno, 2015 GTI, intake only"}, {"label": "AWE AirGate, Stage 2 tune", "v": 16, "note": "vendor; hp as stated"}, {"label": "034 X34 near redline", "v": 30, "note": "vendor: gain approaching redline, not peak"}], "source": "034 blog; UroTuning intake roundup; MyGolfMk7.com independent dyno tests; Racingline product notes. IE's +35 hp claim is a Mk8 Golf R with a Stage 2 tune and is excluded.", "c": {"level": "medium", "n": 4, "note": "Two vendor dynos and two independent tests; conditions differ and are labelled per bar."}}]}, {"n": 2, "title": "Cover and hose", "blocks": [{"t": "text", "b": "Engine cover up at the corners. Intake hose: pliers on the airbox-side clamp, screwdriver on the turbo-side clamp, hose out. SAI: pinch the lock ring and pull it off the airbox. Vacuum line off the box gently; it's reused."}]}, {"n": 3, "title": "Front inlet and airbox out", "blocks": [{"t": "text", "b": "Coolant line out of its clips (lift). Two T25s on the sides of the front inlet, push the inlet down and lift each lock tab, inlet out of the radiator support. Lift the two rubber grommet brackets and the whole airbox comes up.", "only": ["ie", "cts", "other"]}, {"t": "text", "b": "Eight T25s on the lid (keep six for the 034 upper). Breather hose off the box, 7mm clamp at the turbo, lift the upper box and inlet. Panel filter out. Now the baffle inside the lower box: tight, wiggle it out; it's not reused.", "only": ["o34"]}, {"t": "ill", "id": "mk7-intake", "cap": "Full kits replace the whole box; 034 keeps the lower half on its two grommet posts."}]}, {"n": 4, "title": "Coolant line reroute", "only": ["ie"], "caution": true, "blocks": [{"t": "text", "b": "Release the clamp on the factory coolant line, pull the hose back and cap the line immediately with the silicone cap; same on the lower return. Fit IE's silicone hose to the hard line and the radiator barb, one end at a time, quickly. Tighten both clamps."}, {"t": "warn", "b": "Cold engine only. Some coolant loss is normal; a pressurised system here is a burn."}]}, {"n": 5, "title": "Shield / upper in", "blocks": [{"t": "text", "b": "Bolt shield B to A (4 M6 button heads, 4mm allen). Shield under the radiator support, IE's grommets onto the two factory posts, one button head to the passenger radiator support. Rotate the SAI fitting 90° clockwise on its line.", "only": ["ie"]}, {"t": "text", "b": "Mount the SAI provision on the side of the box with the supplied fitting and allen bolt (4 Nm), or the block-off on an R/S3. 034 upper onto the lower box with the six saved T25s.", "only": ["o34"]}, {"t": "torque", "label": "Airbox lid screws (T25)", "nm": 4, "c": {"level": "high", "n": 1, "note": "4 Nm (034 PDF)."}, "only": ["o34"]}, {"t": "text", "b": "Heat shield onto the factory posts and any bracket per the sheet.", "only": ["cts", "other"]}]}, {"n": 6, "title": "Couplers, pipe, SAI, vacuum", "blocks": [{"t": "text", "b": "Two big clamps loose on the short silicone; SAI adapter (or plug) in it, clamp tight; vacuum fitting in. Pick the long coupler for your inlet (stock vs aftermarket TIP), clamps loose, pipe into it, orient to the turbo and the shield. SAI fitting onto the adapter until it clicks; factory vacuum line onto the barb."}]}, {"n": 7, "title": "Relaxed, then tight; filter", "caution": true, "blocks": [{"t": "text", "b": "Seat both couplers fully (turbo inlet and shield). Everything sitting with no tension? Now tighten all clamps."}, {"t": "torque", "label": "Coupler clamp at the turbo inlet", "nm": 5, "c": {"level": "high", "n": 1, "note": "5 Nm (034 TIP guide); IE says 'firmly'."}, "only": ["o34", "ie", "cts", "other"]}, {"t": "text", "b": "Filter onto the velocity stack, clamp. Trim seal around the shield edge (or the carbon lid: loosen the passenger mount bolt, ease the lid in, six M4s started at opposite ends, then everything tight)."}, {"t": "warn", "b": "A coupler clamped under tension walks off the turbo inlet under boost. Relaxed first, tight second."}]}, {"n": 8, "title": "Cover, coolant, start", "blocks": [{"t": "text", "b": "Engine cover on. IE path: check the coolant level and top up. Start it, listen at the couplers, look at the coolant joints. A minute of odd idle is adaptation."}]}], "alsoReplace": [{"name": "Turbo inlet pipe", "why": "The next restriction; IE and 034 sell them and the intake kit ships the matching coupler. IE's needs coil 1 out (10mm stud); 034's M8 bolt is 9 Nm."}, {"name": "PCV / air-oil separator", "why": "Right there with the airbox out; if it's original, do it."}, {"name": "Stage 1 tune", "why": "The intake's gain is mostly unlocked by software."}], "check": {"tab": "Which kit?", "title": "Which kit fits you?", "illId": "mk7-intake", "illCap": "Invasiveness vs. completeness.", "rows": [{"see": "Want it least invasive, factory look", "means": "Upper-box replacement.", "do": "034 P34 (plastic) or X34 (carbon)."}, {"see": "Want the full kit with a real heat shield", "means": "Full replacement.", "do": "IE V2; add the carbon lid if you like."}, {"see": "IS38 planned", "means": "Intake plus inlet pipe.", "do": "IE V2 + IE TIP, or 034 X34 + 034 TIP."}, {"see": "Racingline/APR tune already", "means": "Tune-matched kit.", "do": "R600 or APR per your tuner."}], "c": {"level": "community", "n": 3, "note": "Kit documentation and owner threads."}}, "aftercare": ["Clamps after a week.", "IE: coolant level after the first two drives."], "disagreements": [{"topic": "Power?", "pos": "Vendors: modest gains on stock, more with a tune.", "call": "Sound on stock; real with a tune or IS38."}, {"topic": "Full kit or upper-box?", "pos": "034's approach keeps factory ducting; full kits add shielding.", "call": "Both work. Pick by how much you want to change."}], "sources": ["Integrated Engineering MK7/MQB Cold Air Intake V2 install guide", "034Motorsport X34 and P34 install guides; 034 turbo inlet guide (torques)", "CTS Turbo IT-270 install guide", "IE turbo inlet pipe guide (coil 1 removal)", "FCP Euro Gen 3 engine guide"], "embeds": []}$j$::jsonb, updated_at = now() where id = 'intake-mk7';
update guides set content = $j${"id": "pcv-r32", "title": "Crankcase breather / PCV & valve cover gasket (VR6)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "r32-vr6-top", "alsoFits": "24V VR6: Mk4 R32, Mk4 GTI/Jetta VR6 (24V), Audi A3/TT 3.2, Eos 3.2 — same valve cover and separator", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "5–6 hr (a full afternoon)", "timeRepeat": "3 hr", "difficulty": 3, "cost": "$105 separator · $115 gasket kit", "risk": "Six open intake ports · lots of small fasteners · nose in service position", "why": "On the VR6 the crankcase ventilation isn't a bolt-on valve: the oil separator is built into the front of the valve cover, under the intake manifold. When its diaphragm sticks the engine either pulls a vacuum leak (lean misfire, whistle) or can't vent (pressure pushes oil past the cover gasket and seals). Getting to it is the valve-cover-gasket job, so you do both, and FCP filmed exactly that on a Mk5 R32.", "note": "FCP's step-by-step is the reference and was shot on this car. Owners confirm the afternoon."}, "heroCap": "Under the intake manifold: the valve cover, with the oil separator (the PCV) set into its front on five screws, and the breather hose off the top. The coolant pipe runs alongside.", "lifespan": {"title": "When to expect it", "headline": ["Separator and gasket typically by 100,000 miles; sooner if the car sat"], "earliest": "Whistle or oil at the manifold at 60k", "detail": "Symptoms are either side of the same coin. Stuck open: vacuum leak, lean codes, rough idle, a whistle. Stuck closed: crankcase pressure, oil weeping at the valve cover and around the manifold, sludge and a milky film on the oil from moisture it can't clear. A leaking cover gasket on a VR6 is a reason to suspect the separator, not just the gasket.", "factors": ["Age of the diaphragm", "Short trips (moisture)", "Extended oil changes"], "inspect": ["Oil around the intake manifold base; a whistle at idle; milkiness under the oil cap"], "confidence": {"level": "high", "n": 3, "note": "FCP symptoms list; owner threads agree."}}, "should": {"yesIf": ["Oil build-up around the intake manifold or valve cover", "Whistling with the engine running", "Misfire at idle with lean codes", "Milky film on the oil or sludge under the cap"], "codes": ["P0171", "P0300", "P0507"], "notes": ["Buy both: the oil separator (022 103 515 B) and the valve cover gasket kit (022 103 483 E, with the six plug-tube seals and new bolts). The access is identical, and a new gasket with an old separator leaks again.", "This is the same access as the coolant 'crack pipe' job. If your cooling system is original, do the pipe and thermostat housing in the same session; the manifold is off either way.", "Aftermarket 'catch can' kits for the R32 exist but are rare; the VR6 is port-injected, so the carbon argument doesn't apply. Fix the separator instead."], "confidence": {"level": "high", "n": 3, "note": "FCP procedure on a Mk5 R32; part numbers from FCP and ECS listings."}}, "parts": [{"tier": "oe", "name": "Oil separator (PCV housing)", "pn": "022 103 515 B", "note": "Genuine VW; sits in the valve cover", "price": "$100–120", "links": []}, {"tier": "oem", "name": "Valve cover gasket kit (Elring)", "pn": "022 103 483 E kit", "note": "Gasket, 6 plug-tube seals, bolts", "price": "$100–120", "links": []}, {"tier": "oe", "name": "Intake manifold gasket", "pn": "022 129 717 (confirm by VIN)", "note": "Replace; it's off", "price": "$25", "links": []}, {"tier": "oe", "name": "Oil-resistant RTV (Ultra Black), blue threadlocker", "pn": "—", "note": "Timing-cover joints and the front studs", "price": "$15", "links": []}], "aftermarket": [{"name": "Genuine separator only", "note": "There's no meaningful aftermarket here; the diaphragm has to seal against the cover. Buy VW.", "price": "$100–120", "signal": "OE only", "links": []}], "tools": [{"name": "10mm, 16mm sockets; 5mm and 6mm hex (long ball-end 6mm for the manifold); 10mm triple-square; T20, T25, T30"}, {"name": "Picks, flat screwdrivers, razor blade, extensions; torque wrench 10–13 Nm; jack and stands (bumper bottom screws)"}, {"name": "Drain pan for washer fluid; degreaser; rags for the intake ports"}], "before": ["Engine cold. Battery negative off (you'll be unplugging the coil harness).", "Photograph every connector and vacuum line at the back of the manifold before touching it. There are four lines and a bracket you'll only see by feel.", "Lay a clean sheet out for the manifold, coils and the eleven cover bolts."], "steps": [{"n": 1, "title": "Nose to service position", "blocks": [{"t": "text", "b": "Bumper cover off: eight T25s along the bottom edge, three T25s in each wheel well, both lower grilles (T20), unplug the side markers through the grille openings, disconnect the washer-bottle suction hose (have a pan), four T25s under the lower grilles and two T20s in the main grille opening, two T25s at the top corners by the headlights, then the two T25s to the bumper beam. Pull each corner forward and set the cover somewhere safe."}, {"t": "text", "b": "Behind each headlight, remove the two rear-most T30s. Unclip the hood cable behind the driver's headlight. Remove the top four 16mm bumper-beam bolts and loosen the bottom four almost all the way. Pull the top of the radiator support forward: the nose tilts and the engine opens up."}, {"t": "note", "b": "Twenty minutes that turns a knuckle-buster into a job you can see. Every R32 engine-top write-up does it."}]}, {"n": 2, "title": "Why the nose comes forward", "blocks": [{"t": "text", "b": "The VR6 fills the bay. With the radiator support tilted you can reach the manifold bolts, the brackets behind the manifold and the coils without working blind. FCP: 'achievable in a driveway with hand tools' once you've done this."}]}, {"n": 3, "title": "Intake manifold off", "blocks": [{"t": "text", "b": "Airbox out (clips and tabs; lift). Harness bracket on the driver's side of the head: 10mm nut and stud at the back, T30 at the front; unplug the three throttle-body-side connectors and lay the harness aside. Coil connectors off (lift the tabs with a pick), harness cover off. Walk the main PCV breather hose off the top of the valve cover with a flat screwdriver. Behind the manifold: four vacuum lines by hand and the bracket (10mm triple-square). Throttle body: four 5mm hex. Fuel-line bracket (10mm) on the passenger side. One 10mm triple-square bolt each side of the manifold. Two T30 brackets at the front (dipstick tube, sensors). Vacuum line off the variable-intake solenoid."}, {"t": "text", "b": "Nine manifold bolts, all at the front, long ball-end 6mm hex. Pry the six coils out of the head with a flat screwdriver. Rock the manifold forward to break the gasket's seal and lift it away."}, {"t": "ill", "id": "r32-vr6-top", "cap": "What's under the manifold: valve cover with the oil separator at its front, and the coolant pipe running along the head to the thermostat housing."}, {"t": "warn", "b": "Six open intake ports. Rag them immediately. A dropped bolt into a VR6 port is a head-off job."}]}, {"n": 4, "title": "Valve cover off", "blocks": [{"t": "text", "b": "Eleven 10mm bolts, outer ones first, then the inner. Lift the cover; set it on the bench. Peel off the old gasket and the six plug-tube seals."}]}, {"n": 5, "title": "Swap the oil separator", "caution": true, "blocks": [{"t": "text", "b": "At the front of the cover: five T20 screws hold the separator housing. Remove them, break the housing's seal gently with a flat screwdriver and pop it out. Oil the new housing's gasket, press it in firmly and evenly, five screws snug."}, {"t": "ill", "id": "r32-vr6-top", "cap": "Separator in the front of the cover. It only seats one way; if it's proud on one side, it isn't in."}, {"t": "warn", "b": "Don't lever on the new housing to seat it. Its gasket is the seal that makes the whole job work."}]}, {"n": 6, "title": "New gaskets, cover on", "blocks": [{"t": "text", "b": "New cover gasket into the cover's groove, then the six plug-tube seals. Head face: degreaser on a rag, wiping away from the openings. Razor off the old silicone where the front timing cover meets the head. Dab of oil-resistant RTV in those two spots and at the front corners around the two studs. New bolts in the cover, cover onto the head, tighten in a criss-cross from the middle out."}, {"t": "torque", "label": "Valve cover bolts (10mm ×11)", "nm": 10, "c": {"level": "high", "n": 1, "note": "10 Nm (FCP Euro procedure on a Mk5 R32)."}}]}, {"n": 7, "title": "Manifold on, engine dressed, nose back", "blocks": [{"t": "text", "b": "New manifold gasket pressed into the manifold (pick the old one out; wipe the head face). Manifold on with nothing trapped; all nine bolts started by hand, then tightened middle-out."}, {"t": "torque", "label": "Intake manifold bolts (6mm hex ×9)", "nm": 13, "c": {"level": "high", "n": 1, "note": "13 Nm (FCP Euro procedure on a Mk5 R32)."}}, {"t": "text", "b": "Brackets (T30), variable-intake vacuum line, coils in (tab side per the connectors), harness and cover, manifold side bolts (10mm TS), driver's-side harness bracket (ground stud at the rear hole), PCV breather hose onto the cover, fuel-line bracket, four vacuum lines and their bracket, throttle body (5mm hex, hand-start), airbox and MAF."}, {"t": "text", "b": "Nose: lift it back, four T30s behind the headlights, top beam bolts by hand then all eight to torque (16mm), then the cover in reverse: two beam T25s, side markers, washer hose, grilles, corner screws, bottom edge, wheel wells."}]}, {"n": 8, "title": "Start and check", "blocks": [{"t": "text", "b": "Battery on. Start it: whistle gone, idle steady. Drive, then look at the cover seam and the manifold base for oil after a few heat cycles. Pull the oil cap: gentle suction, not a howl."}]}], "alsoReplace": [{"name": "Coolant pipe and thermostat housing", "why": "Same access; both are age-failed plastic. See its guide and do them in this session."}, {"name": "Spark plugs and coils", "why": "Coils are in your hand and the plugs are exposed."}, {"name": "Intake manifold gasket", "why": "Always, when the manifold is off."}, {"name": "Fuel injector o-rings", "why": "If the fuel rail comes off for room, new o-rings."}], "check": {"tab": "Open or closed?", "title": "Which way did it fail?", "illId": "r32-vr6-top", "illCap": "Two failure modes, one part.", "rows": [{"see": "Whistle, lean codes, rough idle", "means": "Separator stuck open: vacuum leak.", "do": "Separator + gasket."}, {"see": "Oil at the cover seam and manifold base, milky oil cap", "means": "Stuck closed: crankcase pressure.", "do": "Separator + gasket; check the rear main seal for weep too."}, {"see": "Gasket leak, separator fine when tested", "means": "Just an old gasket.", "do": "Replace the separator anyway; the access is the whole cost."}], "c": {"level": "high", "n": 2, "note": "FCP symptom list; owner reports."}}, "aftercare": ["Re-check the cover seam after a week.", "If you skipped the crack pipe, put it on the list."], "disagreements": [{"topic": "Service position or not?", "pos": "Some owners work with the nose in place.", "call": "Tilt it. The manifold bolts alone justify it."}, {"topic": "Separator only or with the gasket?", "pos": "The separator can be changed with the cover on the bench either way.", "call": "Both, always. Same access."}], "sources": ["FCP Euro 'How To Replace A Volkswagen VR6 Valve Cover Gasket & PCV' (Mk5 R32)", "ECS / FCP part listings (022 103 515 B, gasket kit)", "R32 owner threads on PCV symptoms"], "embeds": []}$j$::jsonb, updated_at = now() where id = 'pcv-r32';
update guides set content = $j${"id": "sway-rear-r32", "title": "Rear sway bar upgrade (R32 · 4Motion)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "alsoFits": "4Motion / quattro PQ35 cars with the same rear end: Mk5 R32, Mk6 Golf R, Audi S3 8P, A3 8P quattro, TT 8J quattro. Not the front-wheel-drive GTI.", "category": "Suspension", "kind": "upgrade", "glance": {"timeFirst": "2 hr", "timeRepeat": "1 hr", "difficulty": 2, "cost": "$200–350", "risk": "Car on jack stands · working around the differential and halfshafts · exhaust clearance", "why": "Your R32 understeers because a VR6 sits over the front axle and the Haldex only sends torque rearward once the fronts slip: on the way into a corner it's a nose-heavy front-driver. A stiffer rear bar hands grip back to the front, so it turns in sharper and stays flatter, and on an all-wheel-drive car you can lean on it harder on the exit than a GTI ever could.", "note": "Owner installs on 4Motion cars run a bit longer than on a GTI because the bar has to be worked around the differential; two people helps."}, "heroCap": "Looking up from under the rear of an R32. The differential and Haldex coupling sit in the middle of the subframe with a halfshaft to each hub, and the bar bolts to the subframe either side of them. The bar comes out around the differential, not straight through the middle.", "should": {"yesIf": ["The car pushes wide (understeers) in fast corners and you'd like it more neutral", "You've done tires and want the next real handling step", "You want a mod you can feel on the first drive", "You'd rather not change springs or dampers yet"], "codes": [], "notes": ["Buy the 4Motion bar. Every maker sells a separate rear bar for the R32, S3, Golf R and quattro A3/TT; the front-wheel-drive Mk5 bar is shaped for a subframe with nothing in the middle and will not clear the differential.", "Rear-first still applies on the R32. The stock car is set up to understeer for safety; the rear bar shifts the balance, and the Haldex lets you use the extra rear grip on the exit rather than fear it.", "Trade-offs: a stiffer rear bar lifts the inside rear sooner and makes mid-corner bumps hit both sides. On an AWD car the tail is more forgiving than on a GTI, but the stiffest hole on all-seasons in the rain is still a lot."], "confidence": {"level": "high", "n": 4, "note": "Part fitment from every maker's catalog; dynamics from forum consensus and basic vehicle behaviour."}}, "parts": [{"tier": "aftermarket", "name": "Rear sway bar kit for 4Motion / quattro (bar, bushings, hardware)", "pn": "see options below · R32/S3/Golf R fitment", "note": "Not the GTI bar", "price": "$220–380", "links": []}, {"tier": "oe", "name": "Bracket bolts (×4)", "pn": "factory", "note": "Torque-to-yield style spec; new ones are cheap", "price": "$8", "links": []}, {"tier": "oe", "name": "End link nuts (×2)", "pn": "factory", "note": "Same links as the GTI (034 lists them for both); replace nuts if the nylon insert is tired", "price": "$4", "links": []}], "tools": [{"name": "Jack + two jack stands (or ramps)", "note": "final torque happens with the car on its wheels", "price": "$80–150"}, {"name": "10mm triple-square (XZN) bit", "note": "bracket bolts; decent quality, not a bargain-bin set", "price": "$10"}, {"name": "6mm triple-square bit", "note": "holds the end-link stud; it never turns anything", "price": "$8"}, {"name": "16mm wrench + 15mm wrench", "price": "$20"}, {"name": "Torque wrench, 20–60 Nm range", "price": "$40–80"}, {"name": "Poly bushing grease (if the kit's is stingy), tape or towels to protect the bar's finish", "price": "$10"}], "before": ["Level ground, wheels chocked, car in gear or Park. Jack stands on the rear jack points, never the subframe alone.", "Exhaust cold. The R32's single mid-pipe runs beside the differential to the centre-exit muffler; you'll be reaching past it.", "Check the kit: bar, two bushings, two brackets (if supplied), hardware. Read the kit's sheet; where it gives its own torque values for its own hardware, those win.", "Confirm the bar you bought is the 4Motion fitment before the car goes up. Lay it against the differential from underneath: the centre section should arc clear of the housing."], "steps": [{"n": 1, "title": "Raise the rear and support it", "blocks": [{"t": "text", "b": "Jack the rear and set both stands. Wheels can stay on; you're working inboard of them. A creeper or piece of cardboard makes the next hour nicer."}]}, {"n": 2, "title": "Disconnect the end links from the bar", "blocks": [{"t": "text", "b": "Each end of the bar has a short link with a stud through it. Put the 6mm triple-square into the stud's socket to hold it still, and turn the 16mm nut off. There's no room for a ratchet by the caliper; a wrench is fine, the nut isn't very tight."}, {"t": "ill", "id": "endlink", "cap": "The bit only holds the stud. If you try to turn the bit, it strips. Turn the nut."}, {"t": "warn", "b": "The bar is not under load. Nothing springs when the links come off."}]}, {"n": 3, "title": "Swing the bar free of the links", "blocks": [{"t": "text", "b": "Rotate the bar so each end drops out of its link. Leave the links attached to the trailing arms."}]}, {"n": 4, "title": "Unbolt the two brackets", "blocks": [{"t": "text", "b": "Two bolts per bracket into the subframe, 10mm triple-square. Support the bar as the last bolt comes out; it's heavier than it looks."}]}, {"n": 5, "title": "Work the old bar out around the differential", "blocks": [{"t": "text", "b": "With the brackets off, the bar is free but boxed in by the differential housing above it, the halfshafts either side and the exhaust. Rotate the bar so one arm points down, slide it sideways until that arm clears the halfshaft, then tip and walk the centre section past the differential toward the side with more room (usually away from the exhaust). A second pair of hands on the far end makes this a minute instead of twenty."}, {"t": "ill", "id": "r32-rear-sway-bar", "cap": "The differential is why the GTI procedure doesn't apply here: there's no 'rotate it past the exhaust' with a housing in the middle."}, {"t": "note", "b": "Loosening the muffler hangers buys an inch if you need it. Nothing on the Haldex or the differential needs to come off; if you find yourself reaching for a driveline bolt, stop and re-angle the bar."}, {"t": "warn", "b": "Don't lever on the halfshafts or the Haldex housing to gain room. The shafts' boots tear and the coupling's casting is aluminium."}]}, {"n": 6, "title": "Bushings onto the new bar", "blocks": [{"t": "text", "b": "Grease the inside of each bushing with the supplied poly grease (not petroleum grease, which swells polyurethane). Slide them onto the bar at the same positions as the old ones, then set the brackets over them."}, {"t": "note", "b": "Powder coat scratches easily. Leave the plastic wrap on the bar until it's up in the car."}]}, {"n": 7, "title": "Feed the new bar in", "blocks": [{"t": "text", "b": "Reverse of step 5: centre section past the differential first, then swing each arm up over its halfshaft. Get the brackets to the subframe and start all four bolts by hand. Snug, not torqued, so the bar can still rotate for the setting."}]}, {"n": 8, "title": "Pick your setting and connect the links", "blocks": [{"t": "fork", "q": "Which hole?", "v": [{"label": "Forward (softer)", "when": "Start here", "blocks": [{"t": "text", "b": "Roughly double the stock bar's rate on a 25mm bar. A clear step up in turn-in and flatness with no drama. Drive it a week before you decide you want more."}]}, {"label": "Rearward (stiffer)", "when": "Sticky tires, track days", "blocks": [{"t": "text", "b": "About 2.5× stock on a 25mm bar. Sharper still, with more inside-rear wheel lift and a livelier tail in the wet. Common second step, rare first one."}]}]}, {"t": "text", "b": "Rotate the bar so the chosen hole lines up with each end-link stud, pass the stud through, and start the nuts. Snug only."}]}, {"n": 9, "title": "Lower the car, then torque everything", "caution": true, "blocks": [{"t": "text", "b": "The factory manual says these fasteners get their final torque with the car sitting on its wheels, not hanging on stands. Otherwise the bushings and links are clamped at the wrong angle and you get clunks and early bushing wear. Lower onto ramps, or onto the ground and reach under."}, {"t": "torque", "label": "Bracket bolts (M8, ×4) · factory hardware", "nm": 25, "c": {"level": "single", "n": 1, "note": "Bentley manual value via TDIClub: 25 Nm then a further 45° turn. If your kit supplied its own brackets and bolts, use the kit's number (034: 25 Nm flat, with Loctite)."}, "note": "+45° turn"}, {"t": "torque", "label": "End link nuts (M10, ×2)", "nm": 45, "alt": [35], "c": {"level": "varies", "n": 2, "note": "45 Nm is the factory value for factory hardware. 35 Nm is what 034 specifies for its own nylock hardware. Follow whichever hardware you're actually tightening."}}, {"t": "warn", "b": "A forum regular guessed 50 lb-ft (68 Nm) on these and stretched the bolts. Both fasteners are smaller than they feel. Use the wrench."}]}, {"n": 10, "title": "Test drive and re-check", "blocks": [{"t": "text", "b": "Drive 20–50 miles with a few firm corners, then re-torque all six fasteners. On an R32 a new clunk can also be a halfshaft boot or a loose exhaust hanger you touched; check both before blaming the bar. Clunking over one-wheel bumps means a bracket or link is loose or the bushing wasn't greased."}]}], "check": {"tab": "Pick a setting", "title": "Which setting is right for you?", "illId": "setting", "illCap": "Both holes are on the same bar. Closer to the pivot is stiffer because the lever is shorter.", "rows": [{"see": "Daily driver, all-season tires", "means": "You want turn-in and less lean, not a tail that steps out in the rain.", "do": "Forward hole. Most people never move it."}, {"see": "Summer tires, spirited driving", "means": "The chassis can use more rear roll stiffness before it gets nervous, and the Haldex covers you on the exit.", "do": "Start forward, try rearward after a week. Expect more inside-wheel lift."}, {"see": "Autocross or track", "means": "Balance matters more than comfort, and you'll adjust per event.", "do": "Rearward, and consider adjustable end links so both sides preload evenly."}], "c": {"level": "community", "n": 3, "note": "Forum consensus plus manufacturer stiffness figures. There is no factory guidance; this is a preference."}}, "aftercare": ["Re-torque after the first 20–50 miles, then forget about it.", "A squeak on slow speed bumps is a dry bushing. Some brackets have a grease port; otherwise pull the bracket and re-grease.", "Adjustable end links are the usual next step if you go to the stiff hole: they let you remove preload so the bar isn't twisted at rest."], "disagreements": [{"topic": "End link torque", "pos": "45 Nm (factory) vs 35 Nm (034's hardware) vs 55 Nm (Mk7 guides).", "call": "45 for factory hardware, kit value for kit hardware. Mk7 numbers are a different car and excluded."}, {"topic": "Torque on stands or on the ground?", "pos": "Manufacturer PDFs torque on the lift; the factory manual says curb weight.", "call": "Snug in the air, final torque on the wheels."}, {"topic": "Which hole first?", "pos": "“Full stiff rear” vs “start soft.”", "call": "Start soft. It's a two-minute change later."}, {"topic": "Front bar too?", "pos": "Some R32 owners do both because the nose is heavy.", "call": "Rear first for balance. A front bar (R32 fitment) is a reasonable second on this car, more so than on a GTI."}, {"topic": "GTI bar on an R32?", "pos": "They look alike and cost less.", "call": "No. Different bend; the centre won't clear the differential."}], "sources": ["VWVortex 'DIY: Installing rear sway bar on R32' (owner notes, H&R and Neuspeed installs)", "Neuspeed, H&R, Whiteline, 034 catalog fitments (4Motion/quattro rear bars listed separately from FWD)", "Factory torque values shared with the FSI guide (same bracket and link hardware)", "034Motorsport end-link listing (GTI and R32 share rear links)"], "embeds": [{"id": "S8KnvgU-MLQ", "note": "ECS Tuning on a Mk5/Mk6. Same rear subframe and brackets as your car."}, {"id": "2ts5lTilGiM", "note": "034 install and the why-upgrade case"}], "aftermarket": [{"name": "Neuspeed 25mm rear, 4Motion", "note": "Listed for Golf 5 R32, Golf 6 R, S3 8P and A3 quattro. Tubular, two-hole adjustable, the forum default.", "price": "$300–340", "signal": "Forum favorite", "links": []}, {"name": "H&R 24mm adjustable, 4Motion/quattro", "note": "H&R's R32/TT quattro rear bar; adjustable; the one in the oldest R32 install threads.", "price": "$250–320", "signal": "Well documented", "links": []}, {"name": "Whiteline 24mm adjustable, R32/S3/TT quattro", "note": "Adjustable, often bundled with end links.", "price": "$250–300", "signal": "Value pick", "links": []}, {"name": "034Motorsport adjustable, Mk5 R32", "note": "Solid bar, billet brackets with grease ports. Stiffest of the set.", "price": "$330–380", "signal": "Track-leaning pick", "links": []}], "lifespan": {"title": "When owners do this", "headline": ["Usually the first or second handling mod, right after tires"], "earliest": null, "detail": "The stock bar doesn't wear out, so there's no failure mileage. Owners upgrade it when they notice the car pushing wide in fast corners, typically before touching springs or dampers because it's cheaper and reversible.", "factors": ["Sticky summer tires make the understeer more noticeable", "Lowering springs stiffen the front, which increases the case for a rear bar"], "inspect": ["While you're under there: end links and bushings are often tired by 80,000+ miles; replace them if they're loose or cracked"], "confidence": {"level": "community", "n": 4, "note": "Forum consensus on ordering; the end-link mileage is anecdotal."}}, "heroId": "r32-rear-sway-bar"}$j$::jsonb, updated_at = now() where id = 'sway-rear-r32';
update guides set content = $j${"id": "timing-chain-r32", "title": "Timing chains, guides & tensioners (VR6)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "r32-vr6-chains", "alsoFits": "24V VR6 (Mk4 R32, A3/TT 3.2) for the chain layout; 12V VR6 uses different parts", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "2–3 days · 20–30 hr", "timeRepeat": "—", "difficulty": 5, "cost": "$400–700 parts · $150 tools · plus everything you touch on the way", "risk": "Engine timing · transmission and 4Motion driveline out · the biggest job in this catalog", "why": "The VR6's two timing chains live at the back of the engine against the firewall. Their plastic guide rails wear and the upper tensioner loses grip; the warning is a rattle at idle from the transmission side. Left alone, a guide breaks and the chain jumps. On a Mk5 R32 the chains are behind the DSG, and the DSG has a bevel box and a propshaft bolted to it, so the honest version of this guide is: the chain work is a day, and getting to it is the other two.", "note": "The chain procedure follows the VR6 DIY community has used for twenty years; the 24V parts and cam locks differ from the 12V and are flagged. Access on a 4Motion DSG car is described at the level owners report, not step by step."}, "heroCap": "Back of the engine: the upper chain from the cams down to the intermediate shaft, the lower chain from the intermediate shaft to the crank, each with a guide rail and a tensioner rail. The upper covers come off with the transmission out of the way.", "lifespan": {"title": "When to expect it", "headline": ["Listen from 100,000 miles; act on a rattle"], "earliest": "Guide failures reported from 80k", "detail": "A rattle or ticking at idle from the rear of the engine that changes with revs is the guides or the tensioner. Many VR6s go 200k on the original chains; the plastic rails don't. Once a rail breaks up, pieces end up in the pan and the chain runs loose. That's the point of no return.", "factors": ["Mileage", "Oil change neglect (the tensioner is oil-fed)", "Hard cold starts"], "inspect": ["Cold and warm idle with the hood up and an ear at the transmission side. New noise from the rear is this.", "Oil pan magnet at every change: plastic flakes are guide material."], "confidence": {"level": "high", "n": 4, "note": "Universal in VR6 forums, R32 buyer's guides and the 12V DIY thread."}}, "should": {"yesIf": ["Rattle from the rear of the engine at idle", "Plastic in the oil", "Past 150k with unknown history and you're keeping the car", "Transmission is coming out for another reason (clutch isn't a thing on a DSG car, but a rear main seal or a DSG is)"], "codes": ["P0016", "P0341"], "notes": ["Scope honestly. Chain work: 2–8 hours once you can see the covers (the 12V DIY's own estimate). Getting there on a Mk5 R32: subframe, exhaust, propshaft and bevel box, DSG out, or the engine out. Most owners who've done it either pull the engine or pay a specialist for the access and do the chains themselves.", "Parts are 24V-specific. Buy a complete 24V VR6 timing kit (chains, both guide rails, both tensioner rails, upper tensioner, gaskets) rather than piecing it; the 12V part numbers in the famous Vortex DIY do not fit this engine.", "Cam locks: the 24V needs its own cam-locking tool; the 12V's 3268 plate (or the aluminium-plate trick) doesn't fit 24V cams. Rent or buy the 24V VR6 timing tool set.", "Rear main seal: it's right there once the flywheel/DSG side is open. Do it."], "confidence": {"level": "medium", "n": 4, "note": "Chain layout and technique from the VR6 DIY corpus; 24V specifics and 4Motion access at owner-report level. Torques flagged where they come from the 12V DIY."}}, "parts": [{"tier": "oe", "name": "24V VR6 timing chain kit: upper + lower chains, guide rails, tensioner rails, upper tensioner, gaskets", "pn": "e.g. INA/Febi 24V kit (confirm for BUB)", "note": "Not the 12V kit", "price": "$350–600", "links": []}, {"tier": "oe", "name": "Rear main seal", "pn": "068 198 171 / 24V equivalent (confirm)", "note": "Do it", "price": "$25", "links": []}, {"tier": "oe", "name": "Upper and lower timing cover gaskets / RTV (sensor-safe)", "pn": "kit", "note": "", "price": "$30", "links": []}, {"tier": "oe", "name": "Engine oil and filter", "pn": "—", "note": "Change after; the pan collects plastic", "price": "$60", "links": []}, {"tier": "oe", "name": "DSG-to-engine and propshaft hardware, subframe bolts (torque-to-yield)", "pn": "as found", "note": "Anything TTY you disturb", "price": "varies", "links": []}], "aftermarket": [{"name": "24V VR6 timing tool set (cam locks, crank pin)", "note": "Clone sets are cheap and adequate; the cam lock geometry is the whole point.", "price": "$100–150", "signal": "Required", "links": []}, {"name": "Engine support bar or hoist", "note": "You'll need one or the other.", "price": "$100–300", "signal": "Required", "links": []}], "tools": [{"name": "24V VR6 cam locks and crank locking pin; 27mm socket (upper tensioner bolt) and a long breaker bar"}, {"name": "10, 13, 15, 16, 18mm sockets; 5/6mm hex; triple-squares (DSG and driveline bolts); torque wrenches ¼\" to ½\"; angle gauge"}, {"name": "Engine support bar or hoist; transmission jack; stands; drain pans (oil, coolant, DSG fluid if it comes out)"}, {"name": "RTV, scrapers, magnet, plenty of labelled bags"}], "before": ["Read the Vortex 12V DIY for the chain sequence and photos, then translate to the 24V kit's sheet. Structure is the same; parts and cam locks aren't.", "Decide access before you start: transmission out (DSG + bevel box + propshaft) or engine out. Either is a weekend before you see a chain.", "Order everything TTY you'll disturb. On a 4Motion DSG car that's more than you think."], "steps": [{"n": 1, "title": "Confirm it's the chains", "blocks": [{"t": "text", "b": "Rattle from the rear at idle that follows revs; plastic on the pan magnet; a cam/crank correlation code. If it's a tick from the front instead, look at the tensioner for the accessory belt and the lifters first. This job is too big to do on a guess."}]}, {"n": 2, "title": "Access: transmission out (or engine out)", "caution": true, "blocks": [{"t": "text", "b": "Transmission-out route on a Mk5 R32: battery out; airbox, driver's side engine-bay clutter; exhaust from the downpipe back; propshaft from the bevel box (mark it); front axles from the transmission; subframe lowered or out; DSG unplugged and drained, cooler lines off; engine on a support bar; DSG mount off; bell-housing bolts; DSG and bevel box out as a unit onto a transmission jack. Then the flywheel/driveplate. Now you can see the timing covers."}, {"t": "text", "b": "Engine-out route: many R32 owners judge this easier on a 4Motion car and do the chains, rear main, coolant pipe and mounts on a stand."}, {"t": "warn", "b": "This is where the days go and where things get broken. Bag and label every bolt by location. Propshaft and bevel-box bolts are torque-to-yield and get replaced."}]}, {"n": 3, "title": "Set TDC and lock the cams", "caution": true, "blocks": [{"t": "text", "b": "Turn the engine to cylinder 1 TDC on the marks (crank and cam). Upper timing cover off. The 24V cam lock tool goes into the slots on the cam ends; if it doesn't drop in, you're not at TDC, or you're 360° out. Check the intermediate shaft mark too."}, {"t": "ill", "id": "r32-vr6-chains", "cap": "Upper chain: cams to intermediate shaft. Lower chain: intermediate shaft to crank. Each has a fixed guide rail and a tensioner rail."}, {"t": "warn", "b": "Locks in before anything else comes off, and the crank doesn't move until they're out again. A VR6 that jumps time bends valves."}]}, {"n": 4, "title": "Upper chain, guides and tensioner", "blocks": [{"t": "text", "b": "Upper tensioner bolt out (27mm, with its crush washer). Upper guide rail and tensioner rail off (hex bolts; note which is the curved fixed rail). Upper chain off the cam sprockets and the intermediate sprocket. Inspect the rails: worn or missing plastic is the noise you heard."}, {"t": "torque", "label": "Upper tensioner bolt (27mm) — 12V value", "nm": 100, "c": {"level": "varies", "n": 1, "note": "The 12V DIY's figure; the 24V kit sheet governs. Flagged as unconfirmed for this engine."}}]}, {"n": 5, "title": "Lower chain, guides and tensioner", "blocks": [{"t": "text", "b": "Lower cover off (RTV-sealed; scrape it). Lower tensioner rail (spring type) and guide rail off, lower chain off the intermediate and crank sprockets. Rear main seal is exposed here: pry the old one out, drive the new one in square with a block of wood."}]}, {"n": 6, "title": "New chains on the marks", "caution": true, "blocks": [{"t": "text", "b": "Lower chain onto the crank and intermediate sprockets with both marks aligned per the kit sheet, new guide rail and tensioner rail. Upper chain onto the intermediate and both cam sprockets with the cams still locked, new rails, new upper tensioner bolt with its washer. Only now pull the cam locks. Rotate two full turns by hand and confirm the locks drop back in at TDC."}, {"t": "warn", "b": "If the locks don't drop back in after two turns, take the upper chain off and start again. Do not start the engine."}]}, {"n": 7, "title": "Covers, seal, and everything back", "blocks": [{"t": "text", "b": "RTV the lower cover and fit it; upper cover with its gasket. Flywheel/driveplate with new bolts to the kit's torque. DSG and bevel box back on the jack, bell-housing bolts, mounts, propshaft (new TTY bolts, marks aligned), axles, subframe (TTY, to spec with angle), exhaust, cooler lines, harness, airbox, battery. Fresh oil and filter."}]}, {"n": 8, "title": "First start", "blocks": [{"t": "text", "b": "Crank with coils unplugged for a few seconds to prime, then start. It should be quiet immediately and stay quiet at every idle after. DSG: check fluid level per its guide if any came out. Drive gently, re-check for leaks at both covers and the rear main."}]}], "alsoReplace": [{"name": "Rear main seal", "why": "Exposed with the lower chain off; leaks on high-mileage VR6s."}, {"name": "Engine and transmission mounts", "why": "Everything's out; collapsed mounts are common on R32s."}, {"name": "Coolant pipe, thermostat housing, PCV", "why": "If the engine is out, the top of it is trivial. See their guides."}, {"name": "DSG service and Haldex", "why": "DSG is drained anyway; the Haldex is ten minutes while you're under there."}, {"name": "Bevel box and rear diff oil", "why": "Propshaft's out; plugs are right there."}], "check": {"tab": "Is it the chains?", "title": "Is that noise the chains?", "illId": "r32-vr6-chains", "illCap": "Rear of the engine at idle is the tell.", "rows": [{"see": "Rattle from the transmission side at idle, follows revs", "means": "Guides/tensioner.", "do": "This job. Soon."}, {"see": "Tick from the front, worse cold, fades warm", "means": "Lifters or the accessory tensioner.", "do": "Not the chains; check those first."}, {"see": "Plastic flakes on the pan magnet", "means": "A guide is breaking up.", "do": "Stop driving it hard; this job."}, {"see": "P0016 / P0341 and rough running", "means": "Chain has moved.", "do": "Tow it. Don't start it again."}], "c": {"level": "high", "n": 3, "note": "VR6 forum consensus."}}, "aftercare": ["Oil and filter at 500 miles to clear debris.", "Listen at every cold start for a month."], "disagreements": [{"topic": "Transmission out or engine out?", "pos": "Both camps on R32 forums.", "call": "On a 4Motion DSG car, engine out is often the easier of two hard roads. Pick based on your hoist."}, {"topic": "Home job?", "pos": "'2–8 hours' (12V DIY, chain work only) vs a full weekend-plus (R32 owners, total).", "call": "5 out of 5. Doable with time, tools and a second person; most owners pay for the access at least."}, {"topic": "Chains too, or just guides?", "pos": "Chains rarely wear; guides do.", "call": "Kit. You're not coming back."}], "sources": ["VWVortex 'DIY – Replacing timing chains, tensioners and guides on a 12v VR6' / GruvenParts mirror (structure, technique, tools)", "R32 forum threads on Mk5 chain noise, access and engine-out vs transmission-out", "24V VR6 timing kit listings (INA, Febi) and tool-set listings", "VWVortex 'Common MKV R32 Issues Report'"], "embeds": []}$j$::jsonb, updated_at = now() where id = 'timing-chain-r32';
update guides set content = $j${"id": "turbo-kit-r32", "title": "Turbo kit (complete systems)", "fits": "2008 VW R32 · 3.2 VR6 (BUB) · DSG · 4Motion", "heroId": "r32-turbo-kit", "alsoFits": "HPA and 034 also sell versions for the Mk4 R32, Audi A3 8P 3.2 and TT 3.2; hardware differs by chassis", "category": "Forced induction", "kind": "upgrade", "variants": {"question": "Which kit are you planning around?", "hint": "Complete systems only: turbo, manifold, downpipe, plumbing, fuelling and software in one box. Piecemeal builds are a different conversation.", "options": [{"id": "dtm", "label": "HPA DTM (EFR 7670, ~7 psi)", "when": "Entry tier. 340 hp on a Mk5 with stock fuelling. The turbo that doesn't feel like a turbo.", "brand": true}, {"id": "ft", "label": "HPA FT-410 / FT-470 (EFR 7670, 16–22 psi)", "when": "Adds the liquid-cooled intake manifold and bigger support parts. 410–470 hp.", "brand": true}, {"id": "ftx", "label": "HPA FTX (EFR 8374)", "when": "500+ hp under 20 psi. The DSG becomes the limit.", "brand": true}, {"id": "o34", "label": "034Motorsport Stage 1 / 2", "when": "$5,895 with software and fuelling; ~300 whp on Stage 1; Stage 2 adds the head spacer.", "brand": true}, {"id": "jdy", "label": "JDY Performance", "when": "Built to order by an R32 specialist; specs by quote.", "brand": true}], "brandSpecific": true}, "glance": {"timeFirst": "3–5 days · 30–40 hr", "timeRepeat": "—", "difficulty": 5, "cost": "$6,000–14,000 kit · $2,000–6,000 in things that aren't in the box", "risk": "Compression, fuelling, heat and a DSG with a torque limit · a wrong step costs an engine", "why": "Naturally aspirated, a 3.2 VR6 makes 250 hp and sounds like the best engine VW ever built. Turbocharged, the same block makes 340 to 500+ with all-wheel drive to put it down. Complete kits from HPA and 034 exist because the VR6 turbo recipe has been worked out over twenty years: a cast manifold that keeps the O2 sensors where the DSG expects them, a compression drop, bigger injectors, software, and heat management. This guide is about choosing a kit, understanding what it does to the car, and everything you'll need that isn't in the box.", "note": "Written from HPA's published tiers and contents, 034's Stage 1 release thread and the R32 community. No complete public install PDF exists for the Mk5, so the install section is a map, not turn-by-turn."}, "heroCap": "Schematic of a single-turbo VR6: exhaust manifold → turbo → downpipe; compressed air → intercooler (air-to-water in HPA's manifold) → intake; oil and coolant lines to the turbo; bigger injectors and software to match. Not a recreation of any kit's install photos.", "lifespan": {"title": "When owners do this", "headline": ["When the car is otherwise sorted and the owner has a plan for the DSG"], "earliest": null, "detail": "Owners who turbo an R32 have usually done the maintenance first (timing chains, coolant pipe, DSG and Haldex service) because the kit puts every one of those under more stress, and because the install has the front of the engine apart anyway.", "factors": ["Maintenance state of the engine", "DSG health (clutch packs are the limit)", "Budget for the parts not in the box"], "inspect": ["Compression test and oil analysis before you spend a dollar on a kit"], "confidence": {"level": "community", "n": 3, "note": "R32 community consensus."}}, "should": {"yesIf": ["You want 340+ hp with AWD and a car that still drives to work", "The engine is healthy (compression test, no chain noise)", "You have a budget for the whole project, not the kit price"], "codes": [], "notes": ["Compression. HPA's kits all include a 4 mm compression-reduction kit (a head spacer, taking the 11.3:1 VR6 to about 7.5:1 on their spec); 034's Stage 1 runs stock compression at low boost and Stage 2 adds a spacer (8.5:1 on the Mk5). A spacer means the head comes off. That's the difference between a two-day and a four-day install and it's the single biggest decision in the project.", {"text": "DTM on a Mk5: HPA states 340 hp rather than 350 because of the stock fuelling on the Mk5. It runs about 7 psi on a stock-compression-ish setup with the spacer; owners describe it as an R32 that pulls harder everywhere rather than a boosted car.", "only": ["dtm"]}, {"text": "FT-410 and FT-470 add HPA's liquid-cooled cast intake manifold (air-to-water intercooling) and run 16–22 psi. That's where the kit stops being a bolt-on and becomes a project: chargecooler plumbing, a coolant loop and pump, and the fuel system that 470 hp asks for.", "only": ["ft"]}, {"text": "FTX (EFR 8374): 500+ hp and 500+ lb-ft under 20 psi. At this level the stock DSG clutch packs are the limit; budget a TCU tune and clutch pack work, or don't buy this tier.", "only": ["ftx"]}, {"text": "034 Stage 1: about 300 whp (280 on stock exhaust), stock compression, FMIC. Their notes say the bumper reinforcement and core support need clearancing for the intercooler and the heat shield for the turbo. Stage 2 adds their head spacer for more boost.", "only": ["o34"]}, {"text": "JDY builds R32 turbo cars for a living; their kits are specified per customer. Ask for the parts list and software plan in writing before you commit, and ask what they assume about the DSG.", "only": ["jdy"]}, "The DSG. The DQ250's clutch packs are the accepted weak point past roughly 400 lb-ft (community figure). Every tier above DTM wants a TCU tune at minimum; FT-470 and FTX want clutch pack upgrades. Plan for it; it's not in any kit.", "Emissions. A turbo kit relocates the cats or removes them, changes the O2 sensor plumbing and adds hardware the factory ECU doesn't expect. HPA's software integrates the emissions controls; even so, this is not a smog-legal modification in most US states. Know your inspection regime."], "confidence": {"level": "medium", "n": 4, "note": "HPA tier contents and numbers from their listings; 034 from their release thread; DSG limits are community figures."}}, "parts": [{"tier": "aftermarket", "name": "Complete turbo kit", "pn": "the kit you chose above", "note": "Turbo, manifold, downpipe, plumbing, injectors, FPR, lines, software, boost controller", "price": "$6,000–14,000", "links": []}, {"tier": "aftermarket", "name": "NOT IN THE BOX: head gasket set, head bolts, timing tools (spacer kits)", "pn": "—", "note": "HPA includes the spacer, not the gasket set or bolts", "price": "$300–500", "links": [], "only": ["dtm", "ft", "ftx", "o34"]}, {"tier": "aftermarket", "name": "NOT IN THE BOX: colder plugs (one range), coils if original", "pn": "NGK BKR7EIX or kit spec", "note": "", "price": "$100–300", "links": []}, {"tier": "aftermarket", "name": "NOT IN THE BOX: fuel pump (in-tank) for FT-470 and above", "pn": "per kit maker", "note": "", "price": "$300–600", "links": [], "only": ["ft", "ftx"]}, {"tier": "aftermarket", "name": "NOT IN THE BOX: DSG TCU tune; clutch packs for FT-470/FTX", "pn": "HPA / others", "note": "", "price": "$800–4,000", "links": [], "only": ["ft", "ftx"]}, {"tier": "aftermarket", "name": "NOT IN THE BOX: gauges (boost, oil pressure, AFR), oil and coolant, exhaust from the downpipe back", "pn": "—", "note": "Your cat-back must meet the kit's downpipe flange", "price": "$500–2,000", "links": []}, {"tier": "oe", "name": "NOT IN THE BOX: every gasket, o-ring and TTY bolt you disturb; new manifold studs", "pn": "—", "note": "", "price": "$200", "links": []}], "aftermarket": [{"name": "HPA Motorsports EFR kits (DTM / FT-410 / FT-470 / FTX)", "note": "The most complete systems for this car: cast manifold with factory-position O2 bungs, stainless downpipe with flex, spacer kit, 500 mL injectors, FPR, plumbing, oil/water lines, software, boost controller. Liquid-cooled intake manifold from FT-410 up. DTM about $8,900.", "price": "$8,900–14,000", "signal": "Most complete", "links": [{"store": "HPA VR6 turbo program", "url": "https://www.hpamotorsports.com/collections/vr6-single-turbo-program"}]}, {"name": "034Motorsport Stage 1 / Stage 2", "note": "Stage 1 $5,895 with hardware, software and fuelling; FMIC; ~300 whp. Stage 2 head spacer for more boost. Mk5 R32 and A3 kits differ in intake, intercooler and plumbing.", "price": "$5,900 + Stage 2", "signal": "Value complete kit", "links": []}, {"name": "JDY Performance", "note": "R32 specialist; turbo programs built to order. Get the spec in writing.", "price": "by quote", "signal": "Specialist build", "links": []}, {"name": "VF Engineering supercharger (alternative)", "note": "The non-turbo route: centrifugal supercharger kit, around 100 hp over stock, stock compression, simpler install. Different character; instant response, no spacer.", "price": "$6,000–7,000", "signal": "Supercharger alternative", "links": []}], "tools": [{"name": "Everything in the PCV and coolant pipe guides (nose forward, manifold off), plus: engine support bar or hoist, torque wrenches ¼\" to ½\" with angle gauge"}, {"name": "Head spacer tiers: 24V cam locks and crank pin, head bolt socket, straight edge; a clean bench", "only": ["dtm", "ft", "ftx"]}, {"name": "AN wrenches, hose-clamp pliers, a die grinder for clearancing (034: bumper beam, core support, heat shield)", "only": ["o34"]}, {"name": "VCDS or equivalent for adaptation and logging; a wideband AFR gauge for the first drives"}], "before": ["Compression test and an oil analysis. A tired engine doesn't get better with boost.", "Do the maintenance first: timing chains if noisy, coolant pipe and thermostat housing, PCV/valve cover, DSG and Haldex service, plugs and coils. The kit stresses every one of them.", "Read the kit's parts list against this guide's 'not in the box' list and order all of it before the car comes apart.", "Book the DSG software at the same time as the engine software; you don't want to drive 400 lb-ft through a stock TCU map while you wait."], "steps": [{"n": 1, "title": "Where the power comes from", "blocks": [{"t": "text", "b": "Stock, the 3.2 VR6 is rated 250 hp and 236 lb-ft. Every complete kit sits somewhere on the chart below; the numbers are the makers' claims, at the crank unless marked, and the Mk5 DTM figure is HPA's own correction for this car's stock fuelling."}, {"t": "chart", "title": "Manufacturer-claimed peak horsepower", "unit": "hp", "baseline": "Stock R32", "bars": [{"label": "Stock R32", "v": 250}, {"label": "034 Stage 1", "v": 300, "note": "whp, kit spec (280 on stock exhaust)"}, {"label": "HPA DTM (Mk5)", "v": 340, "note": "7 psi, stock fuelling"}, {"label": "HPA FT-410", "v": 410, "note": "16 psi"}, {"label": "HPA FT-470", "v": 470, "note": "19–22 psi"}, {"label": "HPA FTX (EFR 8374)", "v": 500, "note": "'500+' under 20 psi"}], "source": "HPA and 034 published figures; 034's is wheel horsepower. Not dyno-verified by this guide.", "c": {"level": "medium", "n": 3, "note": "Manufacturer claims, cross-listed by two retailers."}}, {"t": "text", "b": "Torque is what you feel and what the DSG has to survive:"}, {"t": "chart", "title": "Manufacturer-claimed peak torque", "unit": "lb-ft", "baseline": "Stock R32", "bars": [{"label": "Stock R32", "v": 236}, {"label": "HPA DTM", "v": 360}, {"label": "HPA FT-410", "v": 420}, {"label": "HPA FT-470", "v": 500}, {"label": "HPA FTX", "v": 500, "note": "'500+'"}, {"label": "DQ250 DSG comfort zone", "v": 400, "note": "community figure for stock clutch packs"}], "source": "HPA figures; 034 doesn't publish torque; DSG figure is R32-forum consensus.", "c": {"level": "community", "n": 3, "note": "Torque claims from HPA; DSG limit is community experience."}}]}, {"n": 2, "title": "What comes off", "blocks": [{"t": "text", "b": "Nose to service position; airbox and intake; intake manifold (PCV guide, steps 1–3); both exhaust manifolds and the downpipe with the cats (headers guide, steps 1–4); the cat-back's front section if the kit's downpipe flange differs; belly pans; on 034 kits, the bumper beam and core support for the FMIC. Coolant drained (you're into the cooling system for the turbo's water lines and, on HPA FT kits, the chargecooler loop)."}, {"t": "ill", "id": "r32-turbo-kit", "cap": "Schematic of the finished system. Exhaust side on the firewall side of the VR6; intake side toward the radiator."}]}, {"n": 3, "title": "Compression drop (spacer tiers)", "only": ["dtm", "ft", "ftx", "o34"], "caution": true, "blocks": [{"t": "text", "b": "HPA's spacer kits and 034's Stage 2: the head comes off. Timing chains locked at TDC with the 24V tools, head bolts out in sequence, head off, faces cleaned, spacer between two head gaskets per the kit's sheet, head on with new bolts to the factory sequence and angle, chains re-timed and checked with two turns by hand. This is the timing chain guide's discipline applied to a head job; if the chains and guides are old, this is the moment they get replaced too."}, {"t": "warn", "b": "A head off a VR6 in the car, against the firewall, with the chains behind it: this is the hardest single step in this app. Many owners have the spacer done by a shop and bolt the kit on themselves afterward. That's a legitimate plan."}]}, {"n": 4, "title": "Exhaust side: manifold, turbo, downpipe", "blocks": [{"t": "text", "b": "Kit manifold on with new gaskets and studs (its O2 bungs sit where the factory ones did, which is why the DSG keeps behaving). Turbo to the manifold flange. Heat shield per the kit. Downpipe to the turbo, then to your cat-back's front joint (adapt or replace the front section). O2 sensors into the kit's bungs. Wastegate and boost controller plumbing per the kit."}, {"t": "warn", "b": "Manifold studs, again. New ones, anti-seize, and torque in a criss-cross; a leak here is a ticking you'll chase for weeks."}]}, {"n": 5, "title": "Oil and coolant to the turbo", "caution": true, "blocks": [{"t": "text", "b": "Oil feed from the kit's tap (filter housing or gallery) with the supplied stainless line; oil return to the pan or the kit's fitting, gravity-fed and never uphill. Coolant lines per the kit, tee'd into the heater or block circuit as specified. Route every line away from the manifold and secure it; a chafed oil line on a hot turbo is a fire."}, {"t": "warn", "b": "Return line: no kinks, no uphill run, no small bore. A turbo that can't drain oil smokes out its seals in a week."}]}, {"n": 6, "title": "Intake side: intercooling, manifold, plumbing", "blocks": [{"t": "text", "b": "HPA FT/FTX: the liquid-cooled cast intake manifold replaces the factory manifold; its water core needs a coolant loop with a front heat exchanger and a pump, routed and bled like a second cooling system. DTM: charge plumbing to the factory manifold per the kit.", "only": ["dtm", "ft", "ftx"]}, {"t": "text", "b": "034: front-mount intercooler behind the clearanced bumper beam, charge pipes to the factory manifold; check the FMIC's clearance to the core support before final assembly.", "only": ["o34"]}, {"t": "text", "b": "Injectors (500 mL on HPA kits) into the rail with new o-rings; FPR per the kit; MAF/intake per the kit's inlet. Every silicone joint clamped relaxed first, tight second."}]}, {"n": 7, "title": "Software, then the first start", "caution": true, "blocks": [{"t": "text", "b": "Load the kit's engine software (and the DSG software you booked). New colder plugs. Oil and coolant filled and bled. Crank with coils unplugged to build oil pressure and fill the turbo's line, then start. Idle, watch for leaks at every oil and coolant joint and every exhaust flange. Let it reach temperature; check the chargecooler loop for air if fitted."}, {"t": "warn", "b": "First drives with a wideband AFR gauge and boost gauge in view, at the kit's lowest boost setting. Lean under boost is how VR6s die. Log, don't guess."}]}, {"n": 8, "title": "Break-in and re-check", "blocks": [{"t": "text", "b": "500 gentle miles, then re-torque manifold and downpipe hardware, re-check every clamp and line, change the oil (spacer tiers: the head gasket set's first heat cycles put debris in it). Only then raise boost per the kit's stages."}]}], "alsoReplace": [{"name": "Timing chains and guides", "why": "If the head is coming off for a spacer, the chains are right there. Don't put a turbo on a rattling VR6."}, {"name": "Coolant pipe, thermostat housing, PCV/valve cover", "why": "All under the manifold you're removing anyway."}, {"name": "Clutch packs / TCU software", "why": "FT-470 and FTX: the DSG is the weak link. Budget it as part of the kit."}, {"name": "Brakes and tyres", "why": "Doubling the power on 345 mm brakes and all-seasons is a decision too. R32 brake guides cover pads and rotors; tyres are on you."}, {"name": "Engine and transmission mounts", "why": "Torque doubles; soft mounts let the manifold and downpipe move against everything."}], "check": {"tab": "Which tier?", "title": "Which tier is right for your car?", "illId": "r32-turbo-kit", "illCap": "Power, budget, and how much of the car you're willing to open up.", "rows": [{"see": "Daily driver, want it noticeably faster, no head work", "means": "Low boost, stock-ish compression.", "do": "034 Stage 1 (no spacer) or HPA DTM (spacer included; more complete)."}, {"see": "Want 400+ and will do the head", "means": "Spacer tier with fuelling.", "do": "HPA FT-410; plan the DSG tune."}, {"see": "Want 500 and know what that means for the DSG", "means": "Top tier, clutch packs, full fuel system.", "do": "HPA FTX or a JDY build; budget the transmission."}, {"see": "Want more power with the least disassembly", "means": "Supercharger.", "do": "VF Engineering; a different guide when we write it."}], "c": {"level": "community", "n": 3, "note": "Community consensus plus manufacturer tiering."}}, "aftercare": ["Oil at 500 miles, then every 5k with a turbo-rated oil.", "Log AFR and boost for the first month; a drift is a leak.", "Re-torque exhaust hardware after the first heat cycles.", "Watch coolant level daily for two weeks: the chargecooler loop and the turbo lines are new places to leak."], "disagreements": [{"topic": "Spacer or not?", "pos": "034 Stage 1 runs stock compression; HPA includes a spacer in every tier.", "call": "Low boost can live at stock compression; anything you'll want more from later wants the spacer, and doing it once is cheaper than twice."}, {"topic": "DSG limit", "pos": "Figures from 350 to 450 lb-ft on the forums.", "call": "Treat 400 as the line and tune the TCU at any tier above DTM."}, {"topic": "Home install?", "pos": "Vendors say 'for your technician'.", "call": "5 out of 5. The bolt-on parts are within reach of someone who's done the manifold-off jobs in this app; the spacer is where most owners bring in a shop."}], "sources": ["HPA Motorsports EFR single-turbo program (tiers, contents, Mk5 fuelling note) via UroTuning and GMP listings", "Audizine: 034Motorsport 3.2 24V VR6 Stage 1 turbo kit release thread (price, whp, clearancing, Stage 2 spacer)", "VWVortex R32 forced-induction and DSG threads (clutch pack limits)", "Motorsport Calibrations R32 turbo build guide (context for big-turbo territory)"], "embeds": []}$j$::jsonb, updated_at = now() where id = 'turbo-kit-r32';
update guides set content = $j${"id": "water-pump-mk7", "title": "Water pump & thermostat housing", "fits": "2015–2021 VW GTI (Mk7 / Mk7.5) · 2.0T TSI Gen 3", "heroId": "mk7-waterpump", "alsoFits": "2015–18 Golf, Golf R, Alltrack · 2014–17 Jetta/Passat 1.8T · 2013–17 Beetle · 2017–18 Macan 2.0 (FCP's fitment list); 2019+ GTI is the same layout with later part revisions", "category": "Engine", "kind": "repair", "glance": {"timeFirst": "6 hr to a full day", "timeRepeat": "4 hr", "difficulty": 3.5, "cost": "$150–300 pump + housing · $40 coolant", "risk": "Fuel pressure at the HPFP · intake manifold off · plastic coolant fittings · aluminium throttle-body screws", "why": "If you keep a Mk7 GTI long enough you will do this. The water pump and thermostat live in one plastic module on the front of the block, under the intake manifold, driven by a small belt off the balance shaft. The plastic warps with heat cycles and the module weeps at its joints, so the fix is the whole module, and getting to it means the intake manifold comes off. Book time is five hours; FCP says six to a day for a first-timer.", "note": "FCP Euro's Mk7 GTI procedure is the reference (video and write-up with fastener sizes and torques); DAP and independent shops confirm it as the car's most common failure."}, "heroCap": "Front of the block under the intake manifold: pump and thermostat housing as one module on five captive screws, a belt from the balance-shaft pulley, coolant lines clipped into the housing, and one connector underneath.", "lifespan": {"title": "When to expect it", "headline": ["As early as 25,000 miles; typically around 50,000; almost certainly by 100,000"], "earliest": "25k (FCP)", "detail": "Coolant weeps at the housing joints or the pump's weep hole. Watch for a slowly dropping level with no puddle, a sweet smell after a drive, white or pink crust on the front of the block under the manifold, a low-coolant light, or intermittent overheating. Pulley shaft play or a squeak at idle means the bearing is going too.", "factors": ["Heat cycles (short trips, hot climates)", "Age of the plastic", "Freeze-thaw winters"], "inspect": ["Flashlight down the front of the block below the manifold and dipstick at every oil change"], "confidence": {"level": "high", "n": 4, "note": "FCP, DAP and independent-shop write-ups agree on the failure and the mileage."}}, "should": {"yesIf": ["Coolant level dropping with no visible puddle", "Sweet smell or crust under the manifold on the passenger side", "Low-coolant warning", "Intermittent overheating or a slow-to-warm gauge", "Squeak from the pump at idle or play in the pulley"], "codes": ["P0128", "P2181"], "notes": ["Buy the complete module: pump with the thermostat housing (INA is the OE supplier; 06K 121 011 family, revision by year). Replacing just the housing on an old pump, or the pump on an old housing, is how people do this twice.", "Aluminium housings exist and solve the warping; they cost more and some owners report fit fussiness. A latest-revision plastic module installed clean is a fine repair.", "This job relieves fuel pressure at the high-pressure pump and removes the manifold. Read the whole procedure before you start; the order matters and the fuel step is not optional.", "The Gen 3 has no rubber valve cover gasket to disturb here; the manifold gasket is the one to replace."], "confidence": {"level": "high", "n": 3, "note": "FCP procedure with torques; part strategy from FCP, DAP and NGP."}}, "parts": [{"tier": "oem", "name": "Water pump + thermostat housing module (INA)", "pn": "06K 121 011 (revision by VIN)", "note": "Ships as two pieces; assemble with the five T30s", "price": "$150–300", "links": []}, {"tier": "oe", "name": "Intake manifold gasket", "pn": "06K 129 717 (confirm)", "note": "Manifold's off", "price": "$15", "links": []}, {"tier": "oe", "name": "Coolant, G13 concentrate 1 gal + distilled water", "pn": "G 013 A8J 1G", "note": "", "price": "$30", "links": []}, {"tier": "oe", "name": "Belly-pan clips, any coolant line clip that breaks", "pn": "—", "note": "Order a few", "price": "$10", "links": []}], "aftermarket": [{"name": "INA module (OE supplier)", "note": "What the dealer fits, in the maker's box. Latest revision.", "price": "$150–250", "signal": "OE supplier", "links": [{"store": "FCP Euro procedure", "url": "https://www.fcpeuro.com/blog/how-to-replace-water-pump-thermostat-housing-mk7-vw-gti-beetle-jetta-macan"}]}, {"name": "Aluminium thermostat housing kits (various)", "note": "Metal housing on the pump. Solves warping; check fit reports for your year.", "price": "$250–400", "signal": "Metal housing", "links": []}], "tools": [{"name": "T20, T25, T30 (a stubby T30 for the belt cover), 7mm and 10mm and 13mm sockets, 17mm wrench (fuel line), 24mm socket (turn the crank), M10 triple-square, 32mm oil filter cap socket"}, {"name": "Hook picks (coolant line clips, connectors), flat-band hose-clamp pliers, a mirror and a light, magnetic pickup"}, {"name": "Torque wrench 2–20 Nm; drain pans; safety glasses"}, {"name": "Vacuum coolant fill tool (strongly recommended)"}], "before": ["Engine cold; the fuel system holds pressure and the coolant scalds.", "Safety glasses for the fuel step. Rag around the fitting.", "Photograph every connector and clip on the manifold; several are grey safety clips that must be slid back before they release.", "Bag and label fasteners by step. There are many, and eight of them go into the manifold."], "steps": [{"n": 1, "title": "Top side: cover, intake, duct, fuel pressure", "caution": true, "blocks": [{"t": "text", "b": "Expansion-tank cap off. Engine cover off (clips). Airbox out (clamp at the turbo inlet, MAF unplugged, box lifts). Intake duct at the front: two T20s, cover off, two T25s, and the coolant line clipped to it."}, {"t": "text", "b": "Relieve fuel pressure: slowly loosen the 17mm high-pressure fitting at the high-pressure fuel pump with a rag around it, glasses on. Then pull the clamp back and remove the low-pressure fuel hose from the HPFP."}, {"t": "warn", "b": "The high-pressure side holds real pressure. Slow turn, rag, glasses. Fuel in your eyes ends the day."}]}, {"n": 2, "title": "Underneath: belly pan and the throttle-body side", "blocks": [{"t": "text", "b": "Car up, belly pan off (7× T25 and two clips). From below: unclip the harness, release the big coolant hose with a pick, unplug the MAP sensor behind it, remove the two T30s holding the throttle-body pipe (one hides behind the MAP), 7mm clamp and hose, then wiggle the whole hose assembly out."}]}, {"n": 3, "title": "Coolant pipe, throttle body, brackets", "blocks": [{"t": "text", "b": "Top side: coolant pipe off (2× T30 and a clamp); free the radiator hose below the throttle body with a pick and flat-band pliers (coolant comes out; pan ready). Throttle-body hose clamp (7mm). Manifold bracket: two 13mm up top and one M10 triple-square below, then free the harness from it. Throttle body: four aluminium T30s from behind and below with a mirror; hold it as the last one comes out."}, {"t": "warn", "b": "The throttle-body screws are aluminium. Socket fully seated, steady pressure. A stripped one is a drill-out on a $400 part."}]}, {"n": 4, "title": "Harness, bracket, oil filter housing, sensors", "blocks": [{"t": "text", "b": "Every connector and clip on the manifold: picks for the standard ones, slide the grey lock back on the safety clips first. Bracket under the wiring (2× T30) and its last connector. Oil filter housing off with the 32mm socket. Two more sensors on the manifold (one with a grey lock)."}]}, {"n": 5, "title": "Manifold off", "caution": true, "blocks": [{"t": "text", "b": "Manifold fasteners: 2× 10mm and 8× T30, out with a magnetic pickup in hand. HPFP: a captive T30 on the bracket in front, then the T30 holding the pump to the manifold. Lift the manifold up and away (disconnect the high-pressure line at the rail if it won't clear). Flip it and disconnect the vacuum assembly underneath."}, {"t": "ill", "id": "mk7-waterpump", "cap": "With the manifold off, the pump module is exposed on the front of the block with its belt cover."}, {"t": "warn", "b": "Open intake ports. Rag them now, before the next bolt."}]}, {"n": 6, "title": "Coolant lines, belt cover, belt", "blocks": [{"t": "text", "b": "Pull the clips on the upper and lower coolant lines outward with a pick and wiggle the lines off (pan underneath). Unclip the harness from the belt cover, two T30s (stubby), cover off. Slip the balance-shaft belt off the pump pulley."}]}, {"n": 7, "title": "Pump and thermostat module out", "blocks": [{"t": "text", "b": "Five captive T30s; the lower ones want the mirror and light. Wiggle the module off the block; there's one connector underneath with a safety tab to work free with a pick. Make sure the old thermostat gasket didn't stay on the block."}]}, {"n": 8, "title": "Build and fit the new module", "blocks": [{"t": "text", "b": "New thermostat housing onto the new pump on its dowels, five T30s. Connector on underneath. Module onto the block, five captive T30s snug in a criss-cross."}, {"t": "torque", "label": "Thermostat housing / pump module screws (T30)", "nm": 8, "c": {"level": "high", "n": 1, "note": "8 Nm (FCP Euro Mk7 GTI procedure)."}}, {"t": "text", "b": "Belt back on: 24mm socket on the crank, turn the engine slowly by hand while walking the belt onto the pump pulley. Belt cover (2× T30), harness clipped. Coolant lines clicked into their clips."}]}, {"n": 9, "title": "Everything back, to torque", "blocks": [{"t": "text", "b": "Vacuum assembly under the manifold, manifold on with a new gasket, HPFP T30 and its bracket, then the manifold fasteners."}, {"t": "torque", "label": "Intake manifold (2× 10mm, 8× T30)", "nm": 9, "c": {"level": "high", "n": 1, "note": "9 Nm (FCP)."}}, {"t": "torque", "label": "Manifold bracket: 13mm bolts · M10 triple-square", "nm": 10, "alt": [20], "c": {"level": "high", "n": 1, "note": "13mm bolts 10 Nm; the M10 triple-square below 20 Nm (FCP)."}, "note": "20 Nm for the M10 TS"}, {"t": "text", "b": "Sensors, brackets, harness with the safety clips locked, oil filter housing (32mm) to 2.5 Nm, throttle body."}, {"t": "torque", "label": "Throttle body screws (aluminium T30 ×4)", "nm": 7, "c": {"level": "high", "n": 1, "note": "7 Nm (FCP). Aluminium: not a Newton more."}}, {"t": "text", "b": "Throttle-body pipe from below (2× T30), MAP sensor, big coolant hose, harness, coolant pipe (2× T30), radiator hose, fuel hose with its clamp, high-pressure fitting snug, intake duct and coolant line, airbox, engine cover, belly pan."}]}, {"n": 10, "title": "Fill, bleed, check", "caution": true, "blocks": [{"t": "text", "b": "Vacuum-fill: tool on the expansion tank, pull vacuum (this also proves the system holds), open the valve to a bucket of 50/50 G13 and let it fill until the gauge reads zero. Without the tool: fill slowly, heater on hot, idle to temperature with the cap off, top up as the level drops."}, {"t": "warn", "b": "Check the fuel fitting at the HPFP for weeping before the first drive, with the engine idling and a light on it. Then check the coolant joints after the first full warm-up."}]}], "alsoReplace": [{"name": "PCV / air-oil separator", "why": "Top of the valve cover, four screws, and the airbox is already out. If it's original past 60k, now."}, {"name": "Intake valve carbon cleaning", "why": "The manifold is off and the ports are staring at you. On a 60–80k car this is the moment."}, {"name": "Spark plugs and coils", "why": "Coils are right there with the cover off; if they're due, do them."}, {"name": "Coolant line clips and the intake manifold gasket", "why": "Always, when disturbed."}], "check": {"tab": "Is it the pump?", "title": "Where is the coolant going?", "illId": "mk7-waterpump", "illCap": "The front of the block tells the story.", "rows": [{"see": "Crust or wetness on the front of the block under the manifold", "means": "Pump/housing module.", "do": "This guide."}, {"see": "Squeak at idle, pulley wobbles", "means": "Pump bearing.", "do": "This guide, soon."}, {"see": "Level dropping, no trace anywhere", "means": "Pressure-test first; could be the heater core or a hose end.", "do": "Pressure test before opening the manifold."}, {"see": "Gauge slow to warm, P0128", "means": "Thermostat.", "do": "Module (the thermostat's in it)."}], "c": {"level": "high", "n": 3, "note": "FCP symptoms; shop write-ups."}}, "aftercare": ["Coolant level after each of the first three drives.", "Look at the fuel fitting and the coolant joints at a week.", "Belly pan back on once it's proven dry."], "disagreements": [{"topic": "Plastic or aluminium housing?", "pos": "Aluminium fixes the warp; some report fit issues.", "call": "Either done right lasts. Latest-revision INA is the safe default; aluminium if you want it to be the last time."}, {"topic": "Book time", "pos": "5 hr book; owners 6 to a day.", "call": "Plan a day."}], "sources": ["FCP Euro 'How To Replace The Water Pump And Thermostat Housing On A MK7 Volkswagen GTI' (procedure, fasteners, torques)", "FCP Euro 'Definitive Guide To The Mk7 GTI EA888 Gen 3' (priority, symptoms)", "DAP 'MK7.5 GTI Water Pump Guide'", "NGP Gen 3 TSI maintenance guide; STR Gen 3 weaknesses (aluminium housings)"], "embeds": []}$j$::jsonb, updated_at = now() where id = 'water-pump-mk7';
